        {'word': 'wind-tunnel-testing', 'phonetic': '/ˈwɪnd ˌtʌnl ˈtɛstɪŋ/', 'pos': 'n', 'meaning_vi': 'thử nghiệm mô hình trong hầm thổi gió đo áp lực gió', 'definition': 'a structural design procedure where scale physical models of skyscrapers or bridges are subjected to controlled airflow', 'example': 'Wind-tunnel-testing dictated that the architect round the skyscraper corners to shed high-altitude vortex shedding pressures.', 'example_vi': 'Thử nghiệm trong hầm gió đã buộc kiến trúc sư phải bo tròn các góc tòa nhà chọc trời để giảm áp lực xoáy gió trên cao.', 'synonyms': ['aerodynamic model testing'], 'collocations': ['conduct wind-tunnel-testing'], 'etymology': 'Testing scale models in wind tunnel'},
        {'word': 'vortex-shedding', 'phonetic': '/ˈvɔːrtɛks ˌʃɛdɪŋ/', 'pos': 'n', 'meaning_vi': 'hiện tượng tách xoáy khí động học gây rung lắc nhịp nhàng theo chu kỳ', 'definition': 'an oscillating flow that takes place when fluid flows past a bluff body, creating alternating low-pressure vortices that induce sway', 'example': 'Installing helical strakes around tall industrial steel chimneys disrupts destructive crosswind vortex-shedding.', 'example_vi': 'Lắp đặt các gờ xoắn ốc quanh ống khói thép công nghiệp cao vút giúp phá vỡ hiện tượng tách xoáy ngang gió mang tính phá hoại.', 'synonyms': ['aerodynamic vortex resonance'], 'collocations': ['counteract vortex-shedding'], 'etymology': 'Shedding alternating air vortices'},
