        {'word': 'digital-twin', 'phonetic': '/ˈdɪdʒɪtl twɪn/', 'pos': 'n', 'meaning_vi': 'bản sao số mô phỏng chính xác hoạt động của nhà máy vật lý', 'definition': 'a virtual representation that serves as the real-time digital counterpart of a physical object, assembly line, or process', 'example': "Engineers simulated bottleneck reconfigurations in the factory's digital-twin before moving any physical conveyors.", 'example_vi': 'Các kỹ sư đã mô phỏng việc tái cấu trúc các điểm nghẽn trong bản sao số của nhà máy trước khi dịch chuyển bất kỳ băng chuyền vật lý nào.', 'synonyms': ['virtual replica simulation'], 'collocations': ['construct a digital-twin'], 'etymology': 'Virtual twin of a physical asset'},
        {'word': 'overall-equipment-effectiveness', 'phonetic': '/ˌoʊvərˈɔːl ɪˈkwɪpmənt ɪˌfɛktɪvnəs/', 'pos': 'n', 'meaning_vi': 'hiệu suất thiết bị tổng thể đánh giá tính khả dụng và chất lượng (OEE)', 'definition': 'a framework for measuring manufacturing productivity that combines Availability, Performance, and Quality into a single percentage', 'example': "Implementing predictive maintenance boosted the stamping plant's overall-equipment-effectiveness from seventy-two to eighty-nine percent.", 'example_vi': 'Áp dụng bảo trì dự đoán đã nâng hiệu suất thiết bị tổng thể OEE của nhà máy dập từ 72% lên 89%.', 'synonyms': ['OEE manufacturing metric'], 'collocations': ['maximize overall-equipment-effectiveness'], 'etymology': 'Effectiveness across all equipment parameters'},
        {'word': 'predictive-maintenance', 'phonetic': '/prɪˈdɪktɪv ˈmeɪntənəns/', 'pos': 'n', 'meaning_vi': 'bảo trì dự đoán dựa trên cảm biến rung động và nhiệt độ', 'definition': 'techniques designed to help determine the condition of in-service equipment in order to estimate when maintenance should be performed', 'example': 'Vibration sensors attached to induction motor bearings trigger predictive-maintenance alerts weeks before bearing seizure occurs.', 'example_vi': 'Cảm biến rung động gắn vào ổ bi động cơ cảm ứng phát tín hiệu cảnh báo bảo trì dự đoán vài tuần trước khi xảy ra kẹt bi.', 'synonyms': ['PdM condition-based maintenance'], 'collocations': ['schedule predictive-maintenance'], 'etymology': 'Maintenance based on fault predictions'},
        {'word': 'industrial-internet-of-things', 'phonetic': '/ɪnˈdʌstriəl ˈɪntərnɛt əv θɪŋz/', 'pos': 'n', 'meaning_vi': 'Internet vạn vật trong công nghiệp kết nối cảm biến nhà máy (IIoT)', 'definition': 'the use of smart sensors, instruments, and autonomous devices networked together in industrial computer applications', 'example': 'The automotive assembly plant deployed thousands of wireless IIoT edge gateways to stream torque wrench data continuously.', 'example_vi': 'Nhà máy lắp ráp ô tô đã triển khai hàng nghìn cổng kết nối biên IIoT không dây để truyền dữ liệu súng siết lực liên tục.', 'synonyms': ['IIoT industrial connectivity'], 'collocations': ['implement industrial-internet-of-things'], 'etymology': 'IoT applied to industrial environments'},
        {'word': 'automated-guided-vehicle', 'phonetic': '/ˈɔːtəmeɪtɪd ˈɡaɪdɪd ˈviːəkl/', 'pos': 'n', 'meaning_vi': 'xe tự hành vận chuyển hàng trong kho xưởng thông minh (AGV)', 'definition': 'a portable mobile robot that follows along marked long lines or wires on the floor, or uses radio waves or vision magnets for navigation', 'example': 'Automated-guided-vehicles transport stamped metal panels autonomously between the robotic welding cells and paint booths.', 'example_vi': 'Xe tự hành AGV vận chuyển các tấm kim loại dập hoàn toàn tự động giữa các ô hàn robot và buồng sơn.', 'synonyms': ['AGV factory robot'], 'collocations': ['dispatch automated-guided-vehicles'], 'etymology': 'Vehicle guided automatically along paths'},
        {'word': 'autonomous-mobile-robot', 'phonetic': '/ɔːˈtɒnəməs ˈmoʊbaɪl ˈroʊbɒt/', 'pos': 'n', 'meaning_vi': 'robot di động tự hành tự định vị và tránh vật cản bằng LiDAR (AMR)', 'definition': 'a type of robot that can understand and move through its environment independently using LiDAR and simultaneous localization algorithms', 'example': 'Unlike AGVs on fixed tracks, the autonomous-mobile-robot calculates dynamic paths around human forklifts and spilled pallets.', 'example_vi': 'Khác với AGV chạy theo đường cố định, robot di động tự hành AMR tính toán các đường đi linh hoạt quanh xe nâng và pallet bị đổ.', 'synonyms': ['AMR intelligent transport robot'], 'collocations': ['fleet of autonomous-mobile-robots'], 'etymology': 'Mobile robot navigating autonomously'},
        {'word': 'cyber-physical-system', 'phonetic': '/ˈsaɪbər ˈfɪzɪkl ˌsɪstəm/', 'pos': 'n', 'meaning_vi': 'hệ thống không gian mạng - vật lý tích hợp tính toán và máy móc', 'definition': 'a computer system in which a mechanism is controlled or monitored by computer-based algorithms, seamlessly integrated with the Internet', 'example': 'Industry 4.0 leverages cyber-physical-systems where smart machine parts negotiate processing steps with robotic cells autonomously.', 'example_vi': 'Công nghiệp 4.0 tận dụng các hệ thống không gian mạng - vật lý, nơi các chi tiết máy thông minh tự động đàm phán các bước gia công với robot.', 'synonyms': ['CPS integrated network'], 'collocations': ['architect cyber-physical-systems'], 'etymology': 'Bridging cyber software and physical mechanics'},
        {'word': 'manufacturing-execution-system', 'phonetic': '/ˌmænjʊˈfækʧərɪŋ ˌɛksɪˈkjuːʃən ˌsɪstəm/', 'pos': 'n', 'meaning_vi': 'hệ thống điều hành sản xuất theo dõi tiến độ phân xưởng (MES)', 'definition': 'an information system that tracks and documents the transformation of raw materials into finished goods in real time', 'example': 'Floor operators scan barcode traveler tags into the manufacturing-execution-system to verify lot numbers at every station.', 'example_vi': 'Công nhân phân xưởng quét mã vạch thẻ quy trình vào hệ thống điều hành sản xuất MES để xác minh số lô tại mọi trạm.', 'synonyms': ['MES shop-floor software'], 'collocations': ['integrate manufacturing-execution-system'], 'etymology': 'System executing manufacturing tracking'},
        {'word': 'enterprise-resource-planning', 'phonetic': '/ˈɛntərpraɪz rɪˈzɔːrs ˈplænɪŋ/', 'pos': 'n', 'meaning_vi': 'hệ thống hoạch định tài nguyên doanh nghiệp quản lý cung ứng và tài chính (ERP)', 'definition': 'integrated management of main business processes, mediated by software and technology, uniting finance, inventory, and procurement', 'example': "The factory's ERP software automatically issues purchase orders for raw copper wire whenever floor inventory dips below safety stock.", 'example_vi': 'Phần mềm ERP của nhà máy tự động phát hành đơn đặt mua dây đồng thô bất cứ khi nào hàng tồn kho giảm xuống dưới mức an toàn.', 'synonyms': ['ERP corporate platform'], 'collocations': ['run enterprise-resource-planning'], 'etymology': 'Planning enterprise resources systematically'},
        {'word': 'lead-through-programming', 'phonetic': '/ˈliːd θruː ˈproʊɡræmɪŋ/', 'pos': 'n', 'meaning_vi': 'dạy học robot bằng cách cầm tay dẫn dắt chuyển động trực tiếp', 'definition': 'a robot programming method where an operator manually guides the robotic manipulator through the desired path while positions are recorded', 'example': 'Spray painting robots are frequently calibrated via lead-through-programming to mimic the fluid wrist gestures of master craftsmen.', 'example_vi': 'Robot sơn phun thường được hiệu chỉnh bằng phương pháp cầm tay dẫn dắt để bắt chước các cử chỉ cổ tay uyển chuyển của nghệ nhân.', 'synonyms': ['teach-in programming'], 'collocations': ['utilize lead-through-programming'], 'etymology': 'Programming robot by leading it through paths'},
        {'word': 'teach-pendant', 'phonetic': '/ˈtiːtʃ ˌpɛndənt/', 'pos': 'n', 'meaning_vi': 'bảng điều khiển cầm tay để lập trình và di chuyển robot', 'definition': 'a handheld control box equipped with a screen and emergency stop used to manually jog robot axes and edit motion points', 'example': 'The roboticist jogged joint four using the teach-pendant to set the precise coordinate for picking plastic injection moldings.', 'example_vi': 'Kỹ sư robot đã nhích trục số 4 bằng bảng điều khiển cầm tay để thiết lập tọa độ chính xác nhằm gắp các sản phẩm đúc ép nhựa.', 'synonyms': ['robot hand terminal'], 'collocations': ['jog with teach-pendant'], 'etymology': 'Pendant device for teaching robot axes'},
        {'word': 'cartesian-coordinate-robot', 'phonetic': '/kɑːrˈtiːziən koʊˈɔːrdɪnət ˈroʊbɒt/', 'pos': 'n', 'meaning_vi': 'robot tọa độ Descartes kiểu cổng trục di chuyển theo ba trục X-Y-Z', 'definition': 'an industrial robot whose three principal axes of control are linear and move at right angles to each other (gantry robot)', 'example': 'A heavy-duty cartesian-coordinate-robot palletizes sixty-pound cartons across three adjacent warehouse conveyor lanes.', 'example_vi': 'Robot tọa độ Descartes kiểu cổng trục tải trọng nặng xếp các thùng hàng 60 pound lên pallet trên ba làn băng chuyền liền kề.', 'synonyms': ['gantry robot'], 'collocations': ['assemble cartesian-coordinate-robots'], 'etymology': 'Robot moving along Cartesian XYZ axes'},
        {'word': 'scara-robot', 'phonetic': '/ˈskɑːrə ˈroʊbɒt/', 'pos': 'n', 'meaning_vi': 'robot cánh tay khớp nối tuyển chọn phẳng tốc độ cao lắp ráp linh kiện (SCARA)', 'definition': 'Selective Compliance Assembly Robot Arm: a robot arm that is rigid in the Z-axis and compliant in the XY axes, ideal for fast pick-and-place', 'example': 'High-speed SCARA-robots inserted miniature printed circuit board connectors with three-cycle-per-second rapid throughput.', 'example_vi': 'Robot SCARA tốc độ cao đã cắm các đầu nối bảng mạch in thu nhỏ với năng suất nhanh chóng 3 chu kỳ mỗi giây.', 'synonyms': ['SCARA arm'], 'collocations': ['deploy SCARA-robots'], 'etymology': 'Selective Compliance Articulated Robot Arm'},
        {'word': 'delta-robot', 'phonetic': '/ˈdɛltə ˈroʊbɒt/', 'pos': 'n', 'meaning_vi': 'robot hình tam giác ba cánh tay song song siêu tốc đóng gói thực phẩm', 'definition': 'a parallel robot that consists of three arms connected to universal joints at the base, capable of extreme pick-and-place acceleration', 'example': 'Suspended ceiling delta-robots sorted candies into packaging blister packs at breathtaking speeds exceeding two hundred picks per minute.', 'example_vi': 'Robot delta dạng nhện treo trần đã phân loại kẹo vào vỉ đóng gói với tốc độ ngoạn mục vượt quá 200 lượt gắp mỗi phút.', 'synonyms': ['spider robot parallel manipulator'], 'collocations': ['install delta-robots'], 'etymology': 'Robot forming delta triangular linkage'},
        {'word': 'pneumatic-circuit', 'phonetic': '/njuːˈmætɪk ˈsɜːrkɪt/', 'pos': 'n', 'meaning_vi': 'mạch khí nén điều khiển xi lanh bằng khí nén áp suất', 'definition': 'an interconnected system of compressed air pipes, directional valves, regulators, and cylinders used for automated mechanical motion', 'example': 'Cleanrooms favor pneumatic-circuits over hydraulic systems to eliminate the contamination risks of messy oil leaks.', 'example_vi': 'Phòng sạch ưa chuộng các mạch khí nén hơn hệ thống thủy lực để loại bỏ nguy cơ ô nhiễm do rò rỉ dầu luyn bẩn.', 'synonyms': ['compressed-air logic loop'], 'collocations': ['troubleshoot pneumatic-circuits'], 'etymology': 'Circuit powered by pneumatic air'},
        {'word': 'hydraulic-manifold', 'phonetic': '/haɪˈdrɔːlɪk ˈmænɪfoʊld/', 'pos': 'n', 'meaning_vi': 'khối van thủy lực điều phối lưu lượng dầu áp suất cao', 'definition': 'a manifold that regulates fluid flow between actuators, pumps, and other components in a hydraulic power unit', 'example': 'The heavy stamping press relies on a precision-machined steel hydraulic-manifold to distribute three thousand PSI oil evenly.', 'example_vi': 'Máy ép dập hạng nặng dựa vào khối van thủy lực bằng thép gia công chính xác để phân phối đều dầu áp suất 3.000 PSI.', 'synonyms': ['fluid distribution block'], 'collocations': ['machine a hydraulic-manifold'], 'etymology': 'Manifold manifolding hydraulic fluid'},
        {'word': 'variable-frequency-drive', 'phonetic': '/ˈvɛəriəbl ˈfriːkwənsi draɪv/', 'pos': 'n', 'meaning_vi': 'biến tần điều khiển tốc độ động cơ điện xoay chiều (VFD)', 'definition': 'an electronic device that regulates the speed and rotational torque of an AC electric motor by varying input frequency and voltage', 'example': 'Installing variable-frequency-drives on cooling tower fans slashed industrial electricity consumption by thirty-four percent.', 'example_vi': 'Lắp đặt các biến tần điều khiển tốc độ trên quạt tháp giải nhiệt đã cắt giảm 34% mức tiêu thụ điện năng công nghiệp.', 'synonyms': ['VFD inverter drive'], 'collocations': ['tune a variable-frequency-drive'], 'etymology': 'Drive varying motor electric frequency'},
        {'word': 'proportional-integral-derivative', 'phonetic': '/prəˈpɔːrʃənl ˈɪntɪɡrəl dɪˈrɪvətɪv/', 'pos': 'n', 'meaning_vi': 'bộ điều khiển vòng lặp kín PID triệt tiêu sai số tự động', 'definition': 'a control loop feedback mechanism widely used in industrial control systems to continuously calculate error values and apply corrections', 'example': 'Engineers tuned the proportional-integral-derivative parameters to maintain molten solder bath temperatures within half a degree.', 'example_vi': 'Các kỹ sư đã tinh chỉnh các thông số bộ điều khiển PID để duy trì nhiệt độ bể hàn nóng chảy trong phạm vi nửa độ C.', 'synonyms': ['PID controller loop'], 'collocations': ['tune proportional-integral-derivative gains'], 'etymology': 'Proportional + Integral + Derivative control'},
        {'word': 'closed-loop-feedback', 'phonetic': '/kloʊzd ˈluːp ˈfiːdbæk/', 'pos': 'n', 'meaning_vi': 'phản hồi vòng kín hiệu chỉnh sai lệch dựa trên cảm biến', 'definition': 'a control system that monitors its own output and uses sensor signals to continuously adjust inputs to achieve desired target values', 'example': 'High-precision optical linear encoders provide continuous closed-loop-feedback to compensate for thermal ball screw expansion.', 'example_vi': 'Thước đo quang tuyến tính độ chính xác cao cung cấp phản hồi vòng kín liên tục để bù cho sự giãn nở nhiệt của trục vít me.', 'synonyms': ['feedback control loop'], 'collocations': ['operate with closed-loop-feedback'], 'etymology': 'Control loop that is closed by feedback'},
        {'word': 'optical-encoder', 'phonetic': '/ˈɒptɪkl ɪnˈkoʊdər/', 'pos': 'n', 'meaning_vi': 'bộ mã hóa quang học đo góc quay và vận tốc trục motor', 'definition': 'an electro-mechanical device that converts the angular position or motion of a shaft into an analog or digital output code via light beams', 'example': 'A twenty-four-bit absolute optical-encoder mounted to the motor shaft resolves millions of unique positions per single revolution.', 'example_vi': 'Bộ mã hóa quang học tuyệt đối 24 bit gắn trên trục động cơ phân giải hàng triệu vị trí độc nhất trong mỗi vòng quay.', 'synonyms': ['rotary optical pulse transducer'], 'collocations': ['mount an optical-encoder'], 'etymology': 'Encoder encoding motion via optics'},
        {'word': 'load-cell', 'phonetic': '/ˈloʊd sɛl/', 'pos': 'n', 'meaning_vi': 'cảm biến đo lực và tải trọng chuyển đổi thành tín hiệu điện', 'definition': 'a transducer that is used to create an electrical signal whose magnitude is directly proportional to the physical force being measured', 'example': 'A high-precision strain gauge load-cell verified that the dispensing nozzle applied exactly fifteen Newtons of insertion pressure.', 'example_vi': 'Cảm biến tải trọng gắn điện trở lá đo biến dạng chính xác cao đã xác nhận đầu phân phối tác dụng lực ấn đúng 15 Newton.', 'synonyms': ['force transducer'], 'collocations': ['calibrate a load-cell'], 'etymology': 'Cell measuring mechanical force load'},
        {'word': 'proximity-sensor', 'phonetic': '/prɒkˈsɪmɪti ˈsɛnsər/', 'pos': 'n', 'meaning_vi': 'cảm biến tiệm cận phát hiện vật thể kim loại không cần chạm', 'definition': 'a sensor able to detect the presence of nearby objects without any physical contact, commonly inductive, capacitive, or photoelectric', 'example': 'Inductive proximity-sensors installed along the metal conveyor track signal the PLC whenever a steel pallet arrives at the station.', 'example_vi': 'Cảm biến tiệm cận cảm ứng lắp dọc theo đường băng chuyền kim loại báo tín hiệu cho PLC bất cứ khi nào pallet thép tới trạm.', 'synonyms': ['non-contact detector'], 'collocations': ['wire a proximity-sensor'], 'etymology': 'Sensor sensing object proximity'},
        {'word': 'light-curtain', 'phonetic': '/ˈlaɪt ˌkɜːrtn/', 'pos': 'n', 'meaning_vi': 'hàng rào quang điện an toàn tự ngắt máy khi có người bước vào', 'definition': 'an optoelectronic device used to safeguard personnel in proximity to hazardous moving machinery by transmitting infrared beams', 'example': 'Tripping any beam of the safety light-curtain triggers an instantaneous Category 4 emergency stop on the hydraulic press.', 'example_vi': 'Chạm vào bất kỳ tia nào của hàng rào quang điện an toàn sẽ kích hoạt dừng khẩn cấp cấp 4 ngay lập tức trên máy ép thủy lực.', 'synonyms': ['safety optical barrier'], 'collocations': ['interlock with a light-curtain'], 'etymology': 'Curtain formed of invisible light beams'},
        {'word': 'emergency-stop-interlock', 'phonetic': '/ɪˈmɜːrdʒənsi stɒp ˈɪntərlɒk/', 'pos': 'n', 'meaning_vi': 'khóa liên động nút dừng khẩn cấp cắt nguồn động lực (E-Stop)', 'definition': 'a fail-safe electrical circuit that immediately cuts actuator power and applies friction brakes when an emergency button is depressed', 'example': 'Safety inspectors verified that pulling the emergency-stop-interlock cut three-phase power to all automated packaging conveyors.', 'example_vi': 'Thanh tra an toàn đã kiểm tra việc giật khóa liên động dừng khẩn cấp ngắt điện ba pha cấp cho toàn bộ băng chuyền đóng gói tự động.', 'synonyms': ['E-stop circuit trip'], 'collocations': ['trigger emergency-stop-interlock'], 'etymology': 'Interlocking mechanism for emergency stops'},
        {'word': 'cycle-time-optimization', 'phonetic': '/ˈsaɪkl taɪm ˌɒptɪmɪˈzeɪʃən/', 'pos': 'n', 'meaning_vi': 'tối ưu hóa thời gian chu kỳ sản xuất một đơn vị sản phẩm', 'definition': 'the process of analyzing and refining workstation actions to minimize the time needed to complete one repetitive manufacturing operation', 'example': 'Smoothing robotic blending moves and overlap speeds achieved a twelve percent cycle-time-optimization on the paint line.', 'example_vi': 'Làm mượt các chuyển động phối hợp và tốc độ chuyển tiếp của robot đã đạt mức tối ưu hóa thời gian chu kỳ 12% trên dây chuyền sơn.', 'synonyms': ['takt time reduction'], 'collocations': ['achieve cycle-time-optimization'], 'etymology': 'Optimizing repeated cycle duration'},
        {'word': 'takt-time', 'phonetic': '/ˈtɑːkt taɪm/', 'pos': 'n', 'meaning_vi': 'nhịp sản xuất chuẩn theo tốc độ đặt hàng của khách (Takt time)', 'definition': 'the available production time divided by customer demand rate, setting the rhythm at which a plant must complete units', 'example': 'With an eighty-second takt-time, the assembly plant must roll a completed electric vehicle off the finishing line every minute and twenty seconds.', 'example_vi': 'Với nhịp sản xuất takt-time 80 giây, nhà máy lắp ráp phải xuất xưởng một chiếc xe điện hoàn chỉnh sau mỗi 1 phút 20 giây.', 'synonyms': ['demand pacing beat'], 'collocations': ['synchronize to takt-time'], 'etymology': 'Takt (musical beat/rhythm in German)'},
        {'word': 'lean-manufacturing', 'phonetic': '/liːn ˌmænjʊˈfækʧərɪŋ/', 'pos': 'n', 'meaning_vi': 'sản xuất tinh gọn triệt tiêu lãng phí và tồn kho dư thừa', 'definition': 'a production methodology focused on minimizing waste (muda) within manufacturing systems while simultaneously maximizing productivity', 'example': 'Adopting lean-manufacturing eliminated buffer warehouses by introducing kanban replenishment pulls between machining cells.', 'example_vi': 'Áp dụng sản xuất tinh gọn đã loại bỏ các kho đệm bằng cách giới thiệu cơ chế kéo bổ sung kanban giữa các ô gia công.', 'synonyms': ['Toyota production system methodology'], 'collocations': ['practice lean-manufacturing'], 'etymology': 'Lean production devoid of wasteful fat'},
        {'word': 'kanban-system', 'phonetic': '/ˈkɑːnbɑːn ˌsɪstəm/', 'pos': 'n', 'meaning_vi': 'hệ thống thẻ báo kanban điều phối vật tư tức thời (JIT)', 'definition': 'a visual scheduling system for lean and just-in-time manufacturing that uses visual cards or digital tags to trigger inventory replenishment', 'example': 'Electronic barcode kanban-systems notify forklift operators to deliver stamped door panels whenever a parts rack is emptied.', 'example_vi': 'Hệ thống thẻ báo kanban điện tử thông báo cho tài xế xe nâng giao các tấm cửa dập bất cứ khi nào giá để linh kiện trống.', 'synonyms': ['visual pull workflow'], 'collocations': ['implement a kanban-system'], 'etymology': 'Kanban (signboard in Japanese)'},
        {'word': 'just-in-time-manufacturing', 'phonetic': '/ˌdʒʌst ɪn ˈtaɪm ˌmænjʊˈfækʧərɪŋ/', 'pos': 'n', 'meaning_vi': 'sản xuất đúng thời điểm không lưu kho đệm dư thừa (JIT)', 'definition': 'an inventory strategy where materials are received and processed only as they are needed in the production process', 'example': 'Automakers operate just-in-time-manufacturing so tire deliveries arrive at the factory bay three hours before wheel mounting.', 'example_vi': 'Các hãng xe ô tô vận hành sản xuất đúng thời điểm JIT để các chuyến giao lốp tới cửa nhà máy đúng 3 giờ trước khi lắp vào vành.', 'synonyms': ['JIT inventory management'], 'collocations': ['master just-in-time-manufacturing'], 'etymology': 'Manufacturing just in time for assembly'},
        {'word': 'root-cause-analysis', 'phonetic': '/ruːt kɔːz əˌnæləsɪs/', 'pos': 'n', 'meaning_vi': 'phân tích nguyên nhân gốc rễ tìm nguồn gốc hư hỏng (RCA)', 'definition': 'a structured problem-solving method directed at identifying the fundamental or primary cause of operational failures or defects', 'example': 'Quality engineering conducted a thorough root-cause-analysis to discover why hydraulic seals degraded prematurely in humid weather.', 'example_vi': 'Phòng kỹ thuật chất lượng đã tiến hành phân tích nguyên nhân gốc rễ kỹ lưỡng để tìm hiểu tại sao gioăng thủy lực lại nhanh hỏng khi trời ẩm.', 'synonyms': ['RCA defect investigation'], 'collocations': ['conduct root-cause-analysis'], 'etymology': 'Analyzing the root fundamental cause'},
        {'word': 'six-sigma', 'phonetic': '/sɪks ˈsɪɡmə/', 'pos': 'n', 'meaning_vi': 'phương pháp quản lý chất lượng Six Sigma giới hạn dưới 3,4 lỗi trên một triệu sản phẩm', 'definition': 'a disciplined, data-driven approach and methodology for eliminating defects in any process (aiming for less than 3.4 defects per million)', 'example': 'The precision aerospace bearing foundry achieved Six-Sigma quality certification across its robotic heat-treating cells.', 'example_vi': 'Xưởng đúc ổ bi hàng không vũ trụ chính xác cao đã đạt chứng nhận chất lượng Six Sigma trên các ô nhiệt luyện robot.', 'synonyms': ['DMAIC quality standard'], 'collocations': ['apply six-sigma principles'], 'etymology': 'Six standard deviations from process mean'},
        {'word': 'statistical-process-control', 'phonetic': '/stəˈtɪstɪkl ˈprɒsɛs kənˈtroʊl/', 'pos': 'n', 'meaning_vi': 'kiểm soát quá trình bằng phương pháp thống kê (SPC)', 'definition': 'the application of statistical methods to monitor and control a manufacturing process to ensure it operates at its full potential', 'example': 'SPC control charts tracked inner bore diameters in real time, alerting technicians when cutter wear pushed tolerances toward the upper control limit.', 'example_vi': 'Các biểu đồ kiểm soát quá trình SPC đã theo dõi đường kính lỗ khoan thời gian thực, cảnh báo kỹ thuật viên khi độ mòn dao vượt ngưỡng.', 'synonyms': ['SPC quality monitoring'], 'collocations': ['maintain statistical-process-control'], 'etymology': 'Controlling processes via statistical data'},
        {'word': 'die-casting', 'phonetic': '/ˈdaɪ ˌkæstɪŋ/', 'pos': 'n', 'meaning_vi': 'đúc áp lực kim loại nóng chảy vào khuôn thép', 'definition': 'a metal casting process characterized by forcing molten metal under high pressure into a mold cavity machined from hardened steel dies', 'example': 'Robotic die-casting machines injected molten aluminum alloy into massive water-cooled dies to form engine transmission housings.', 'example_vi': 'Các máy đúc áp lực robot đã ép hợp kim nhôm nóng chảy vào khuôn thép làm mát bằng nước khổng lồ để tạo vỏ hộp số động cơ.', 'synonyms': ['pressure mold casting'], 'collocations': ['operate die-casting machinery'], 'etymology': 'Casting metal using precision steel dies'},
        {'word': 'injection-molding', 'phonetic': '/ɪnˈdʒɛkʃən ˌmoʊldɪŋ/', 'pos': 'n', 'meaning_vi': 'ép phun nhựa nhiệt dẻo tạo hình sản phẩm hàng loạt', 'definition': 'a manufacturing process for producing parts by injecting molten thermoplastic material into a split mold tool under high pressure', 'example': 'A multi-cavity injection-molding machine produces seventy-two medical syringe barrels every sixteen-second cycle.', 'example_vi': 'Một máy ép phun nhựa nhiều lòng khuôn sản xuất 72 thân ống tiêm y tế trong mỗi chu kỳ 16 giây.', 'synonyms': ['thermoplastic molding process'], 'collocations': ['run injection-molding tooling'], 'etymology': 'Molding parts by injecting melted polymer'},
        {'word': 'surface-mount-technology', 'phonetic': '/ˈsɜːrfɪs maʊnt tɛkˈnɒlədʒi/', 'pos': 'n', 'meaning_vi': 'công nghệ dán bề mặt linh kiện điện tử lên bảng mạch (SMT)', 'definition': 'a method for producing electronic circuits in which the components are mounted or placed directly onto the surface of printed circuit boards', 'example': 'High-speed surface-mount-technology pick-and-place lines place miniature 0201 capacitors with sub-millimeter precision.', 'example_vi': 'Dây chuyền gắp đặt công nghệ dán bề mặt SMT tốc độ cao định vị các tụ điện siêu nhỏ 0201 với độ chính xác dưới một milimet.', 'synonyms': ['SMT electronics assembly'], 'collocations': ['utilize surface-mount-technology'], 'etymology': 'Mounting electronic components on surface'},
        {'word': 'reflow-soldering', 'phonetic': '/ˈriːfloʊ ˌsoʊldərɪŋ/', 'pos': 'n', 'meaning_vi': 'hàn đối lưu nóng chảy thiếc kết dính linh kiện SMT', 'definition': 'a process in which a solder paste is used to temporarily attach one or several electrical components to their contact pads, then melted by heat', 'example': 'Populated circuit boards traveled through a ten-zone nitrogen reflow-soldering oven to form permanent metallic interconnections.', 'example_vi': 'Các bảng mạch sau khi dán linh kiện đã đi qua lò hàn đối lưu nitơ 10 vùng nhiệt để tạo ra các mối liên kết kim loại vĩnh cửu.', 'synonyms': ['SMT oven soldering'], 'collocations': ['conduct reflow-soldering'], 'etymology': 'Soldering by reflowing heated solder paste'},
        {'word': 'automated-optical-inspection', 'phonetic': '/ˈɔːtəmeɪtɪd ˈɒptɪkl ɪnˌspɛkʃən/', 'pos': 'n', 'meaning_vi': 'kiểm tra quang học tự động phát hiện lỗi chân hàn bảng mạch (AOI)', 'definition': 'an automated visual inspection of printed circuit boards where a high-resolution camera scans the device for missing components and solder bridges', 'example': 'Automated-optical-inspection flagged a cold solder joint and a tombstoned resistor before boards entered final chassis assembly.', 'example_vi': 'Thiết bị kiểm tra quang học tự động AOI đã cảnh báo một mối hàn nguội và điện trở bị dựng đứng trước khi bảng mạch vào lắp ráp vỏ.', 'synonyms': ['AOI machine testing'], 'collocations': ['pass automated-optical-inspection'], 'etymology': 'Inspecting optics automatically'},
        {'word': 'geometric-dimensioning-and-tolerancing', 'phonetic': '/ˌdʒiːəˈmɛtrɪk dɪˈmɛnʃənɪŋ ənd ˈtɒlərənsɪŋ/', 'pos': 'n', 'meaning_vi': 'kích thước và dung sai hình học theo tiêu chuẩn kỹ thuật (GD&T)', 'definition': 'a system for defining and communicating engineering tolerances through symbolic language on mechanical drawings', 'example': 'Designers applied geometric-dimensioning-and-tolerancing datum callouts to control shaft runout and concentricity strictly.', 'example_vi': 'Các nhà thiết kế đã áp dụng các ký hiệu chuẩn kích thước và dung sai hình học GD&T để kiểm soát độ đảo và độ đồng tâm của trục.', 'synonyms': ['GD&T engineering specs'], 'collocations': ['master geometric-dimensioning-and-tolerancing'], 'etymology': 'Dimensioning and tolerancing geometrically'},
        {'word': 'coordinate-measuring-machine', 'phonetic': '/koʊˈɔːrdɪnət ˈmɛʒərɪŋ məˌʃiːn/', 'pos': 'n', 'meaning_vi': 'máy đo tọa độ 3 chiều kiểm tra kích thước chi tiết cơ khí (CMM)', 'definition': 'a device that measures the physical geometrical characteristics of an object using a sensitive ruby-tipped contact touch probe', 'example': 'The quality lab placed the machined turbine casing onto the granite bed of the coordinate-measuring-machine for volumetric inspection.', 'example_vi': 'Phòng kiểm tra chất lượng đã đặt vỏ tuabin đã gia công lên bàn đá granite của máy đo tọa độ 3 chiều CMM để đo kiểm kích thước.', 'synonyms': ['CMM 3D inspection scanner'], 'collocations': ['measure on a coordinate-measuring-machine'], 'etymology': 'Machine measuring physical 3D coordinates'},
        {'word': 'fieldbus-protocol', 'phonetic': '/ˈfiːldbʌs ˈproʊtəkɒl/', 'pos': 'n', 'meaning_vi': 'giao thức truyền thông bus trường công nghiệp (Profibus, Modbus)', 'definition': 'an industrial network system for real-time distributed control that connects sensors, actuators, and PLCs over a shared digital cable', 'example': 'The automotive line migrated from legacy serial fieldbus-protocols to deterministic industrial Gigabit Ethernet.', 'example_vi': 'Dây chuyền sản xuất ô tô đã chuyển đổi từ các giao thức bus trường nối tiếp cũ sang mạng Ethernet công nghiệp Gigabit định thời.', 'synonyms': ['industrial field communication'], 'collocations': ['implement fieldbus-protocols'], 'etymology': 'Protocol for industrial field devices'},
        {'word': 'human-machine-interface', 'phonetic': '/ˈhjuːmən məˌʃiːn ˈɪntərfeɪs/', 'pos': 'n', 'meaning_vi': 'giao diện người - máy màn hình cảm ứng điều khiển phân xưởng (HMI)', 'definition': 'a user interface or dashboard that connects a person to a machine, system, or device through touchscreens and visual controls', 'example': 'The operator silenced the conveyor fault siren and viewed the diagnostic ladder logic directly on the touchscreen human-machine-interface.', 'example_vi': 'Người vận hành đã tắt còi báo lỗi băng chuyền và xem sơ đồ logic bậc thang chẩn đoán trực tiếp trên màn hình giao diện HMI.', 'synonyms': ['HMI touchscreen console'], 'collocations': ['operate the human-machine-interface'], 'etymology': 'Interface connecting human with machine'},
        {'word': 'edge-computing-gateway', 'phonetic': '/ˈɛdʒ kəmˌpjuːtɪŋ ˈɡeɪtweɪ/', 'pos': 'n', 'meaning_vi': 'cổng tính toán biên xử lý dữ liệu cảm biến tại chỗ', 'definition': 'an industrial computing device installed directly on the factory floor that performs local data analysis before streaming summaries to the cloud', 'example': 'Installing edge-computing-gateways enabled real-time high-speed vibration FFT analysis right beside the stamping presses.', 'example_vi': 'Lắp đặt các cổng tính toán biên đã cho phép phân tích biến đổi Fourier FFT độ rung tốc độ cao theo thời gian thực ngay cạnh máy dập.', 'synonyms': ['industrial edge node'], 'collocations': ['deploy edge-computing-gateways'], 'etymology': 'Gateway computing at the network edge'},
        {'word': 'edge-analytics', 'phonetic': '/ˈɛdʒ ˌænəˈlɪtɪks/', 'pos': 'n', 'meaning_vi': 'phân tích dữ liệu tại thiết bị biên không cần độ trễ đám mây', 'definition': 'an approach to data collection and analysis in which an automated calculation is performed on data at a sensor, network switch or edge device', 'example': 'Sub-millisecond edge-analytics shut down the high-speed stamping press the instant a broken punch die was detected.', 'example_vi': 'Phân tích biên với độ trễ dưới một mili giây đã tắt ngay máy dập tốc độ cao khoảnh khắc phát hiện một khuôn dập bị gãy.', 'synonyms': ['on-premise instant analytics'], 'collocations': ['leverage edge-analytics'], 'etymology': 'Analytics performed at the system edge'},
        {'word': 'computer-aided-manufacturing', 'phonetic': '/kəmˈpjuːtər ˈeɪdɪd ˌmænjʊˈfækʧərɪŋ/', 'pos': 'n', 'meaning_vi': 'sản xuất có máy tính trợ giúp xuất mã gia công G-code (CAM)', 'definition': 'the use of software to control machine tools and related ones in the manufacturing of workpieces based on 3D CAD geometries', 'example': 'CNC programmers utilized computer-aided-manufacturing software to simulate five-axis toolpaths and avoid spindle collisions.', 'example_vi': 'Lập trình viên CNC đã sử dụng phần mềm sản xuất có máy tính trợ giúp CAM để mô phỏng đường chạy dao 5 trục tránh va đập trục chính.', 'synonyms': ['CAM tooling software'], 'collocations': ['program with computer-aided-manufacturing'], 'etymology': 'Manufacturing aided by computers'},
        {'word': 'toolpath-generation', 'phonetic': '/ˈtuːlpæθ ˌdʒɛnəˈreɪʃən/', 'pos': 'n', 'meaning_vi': 'tạo đường dẫn chuyển động của dao cắt gọt trong phần mềm CAM', 'definition': 'the process in CAM software of calculating the precise geometric path that a cutting tool will follow to machine a part from stock material', 'example': 'Advanced algorithms enabled adaptive toolpath-generation, keeping constant cutting cutter engagement to maximize tool life.', 'example_vi': 'Các thuật toán tiên tiến cho phép tạo đường chạy dao thích ứng, duy trì góc tiếp xúc dao cắt ổn định để tối đa hóa tuổi thọ dao.', 'synonyms': ['cutter path calculation'], 'collocations': ['optimize toolpath-generation'], 'etymology': 'Generating the path for machine tools'},
        {'word': 'workpiece-fixturing', 'phonetic': '/ˈwɜːrkpiːs ˈfɪkstʃərɪŋ/', 'pos': 'n', 'meaning_vi': 'đồ gá kẹp chặt phôi gia công chịu lực cắt lớn', 'definition': 'the mechanical devices and clamps used to accurately locate, position, and rigidly secure a metal part during machining operations', 'example': 'Hydraulic workpiece-fixturing clamped the irregular cast iron engine block securely under twenty-five kilonewtons of holding force.', 'example_vi': 'Đồ gá kẹp phôi thủy lực đã kẹp chặt lốc động cơ gang có hình dáng bất quy tắc dưới lực giữ 25 kilonewton.', 'synonyms': ['machining clamps and jigs'], 'collocations': ['secure workpiece-fixturing'], 'etymology': 'Fixturing a workpiece for machining'},
        {'word': 'palletization', 'phonetic': '/ˌpælətɪˈzeɪʃən/', 'pos': 'n', 'meaning_vi': 'hoạt động bốc dỡ và xếp hàng tự động lên các tấm pallet', 'definition': 'the automated action of placing cases, boxes, bags, or drums onto a wooden or plastic pallet in a structured, stable interlocking pattern', 'example': 'Dual-arm palletization robots stacked sixty bags of cement per minute in alternating interlocking layers onto export pallets.', 'example_vi': 'Robot bốc xếp pallet hai cánh tay đã xếp 60 bao xi măng mỗi phút thành các lớp đan xen so le vững chắc lên pallet xuất khẩu.', 'synonyms': ['robotic case stacking'], 'collocations': ['automate palletization'], 'etymology': 'Placing cargo on pallets'},
        {'word': 'depalletizer', 'phonetic': '/diːˈpælətaɪzər/', 'pos': 'n', 'meaning_vi': 'máy dỡ hàng tự động từ pallet xuống băng chuyền phân loại', 'definition': 'an automated machine that unloads cartons or bulk containers from a pallet and places them onto an infeed processing conveyor', 'example': 'The magnetic sweep depalletizer unloaded three tiers of empty aluminum beverage cans simultaneously into the canning filler line.', 'example_vi': 'Máy dỡ pallet quét từ tính đã dỡ đồng thời 3 tầng lon nước ngọt bằng nhôm rỗng vào dây chuyền chiết rót đóng hộp.', 'synonyms': ['bulk unstacking machine'], 'collocations': ['run a depalletizer'], 'etymology': 'Machine that de-palletizes cargo'},
        {'word': 'slip-ring', 'phonetic': '/ˈslɪp rɪŋ/', 'pos': 'n', 'meaning_vi': 'vành trượt truyền tín hiệu và điện năng liên tục qua khớp xoay 360 độ', 'definition': 'an electromechanical device that allows the transmission of power and electrical signals from a stationary to a rotating structure', 'example': 'Gold-plated contacts inside the slip-ring enable endless 360-degree rotation of the robot wrist without twisting internal cables.', 'example_vi': 'Các tiếp điểm mạ vàng bên trong vành trượt cho phép cổ tay robot quay tròn 360 độ vô tận mà không làm xoắn dây cáp bên trong.', 'synonyms': ['rotary electrical joint'], 'collocations': ['install a slip-ring'], 'etymology': 'Ring allowing electrical slip during rotation'},
        {'word': 'harmonic-drive-gearbox', 'phonetic': '/hɑːrˈmɒnɪk draɪv ˈɡɪərˌbɒks/', 'pos': 'n', 'meaning_vi': 'hộp giảm tốc sóng điều hòa triệt tiêu hoàn toàn khe hở cơ học (backlash-free)', 'definition': 'a high-precision gear mechanism that uses an elliptical wave generator and flexible steel cup to achieve high gear reduction with zero backlash', 'example': 'Articulated robot elbows utilize harmonic-drive-gearboxes to ensure smooth, jitter-free positioning under heavy payloads.', 'example_vi': 'Các khớp khuỷu của robot khớp nối sử dụng hộp giảm tốc sóng điều hòa để đảm bảo định vị êm ái, không rung lắc dưới tải nặng.', 'synonyms': ['strain-wave gearing'], 'collocations': ['integrate harmonic-drive-gearbox'], 'etymology': 'Gearing operating via harmonic waves'},
        {'word': 'backlash-compensation', 'phonetic': '/ˈbæklæʃ ˌkɒmpɛnˈseɪʃən/', 'pos': 'n', 'meaning_vi': 'bù độ rơ khe hở giữa các bánh răng trong phần mềm điều khiển', 'definition': 'a controller feature that automatically adds compensating steps to offset mechanical play or looseness when reversing axis motion', 'example': 'Applying software backlash-compensation eliminated micro-positioning errors when the ball screw reversed direction during contouring.', 'example_vi': 'Áp dụng tính năng bù độ rơ bằng phần mềm đã loại bỏ các sai số định vị vi mô khi trục vít me đảo chiều chuyển động viền mép.', 'synonyms': ['gear play correction'], 'collocations': ['calibrate backlash-compensation'], 'etymology': 'Compensating for mechanical backlash'},
        {'word': 'chatter-suppression', 'phonetic': '/ˈtʃætər səˌprɛʃən/', 'pos': 'n', 'meaning_vi': 'triệt tiêu rung chấn dao cắt khi phay tốc độ cao', 'definition': 'techniques and dynamic tool holders designed to eliminate self-excited regenerative vibration between cutting tools and workpieces', 'example': 'Vibration damping boring bars provide passive chatter-suppression, yielding mirror-like surface finishes inside deep turbine holes.', 'example_vi': 'Cán tiện móc lỗ giảm chấn rung cung cấp khả năng triệt tiêu rung chấn thụ động, tạo ra bề mặt nhẵn bóng như gương bên trong lỗ tuabin.', 'synonyms': ['machining vibration dampening'], 'collocations': ['achieve chatter-suppression'], 'etymology': 'Suppressing machining chatter vibrations'},
        {'word': 'spindle-speed-variation', 'phonetic': '/ˈspɪndl spiːd ˌvɛəriˈeɪʃən/', 'pos': 'n', 'meaning_vi': 'thay đổi tốc độ trục chính liên tục để phá vỡ cộng hưởng rung động', 'definition': 'a machining technique that continuously modulates spindle rotational RPM to disrupt resonant regenerative chatter frequencies', 'example': 'Enabling spindle-speed-variation allowed the mill to hog out deep titanium pockets at double the metal removal rate without tool breakage.', 'example_vi': 'Kích hoạt tính năng thay đổi tốc độ trục chính liên tục cho phép máy phay vét các hốc titan sâu với tốc độ cắt gọt kim loại gấp đôi.', 'synonyms': ['speed modulation vibration break'], 'collocations': ['activate spindle-speed-variation'], 'etymology': 'Varying the rotational speed of spindle'},
        {'word': 'coolant-thru-spindle', 'phonetic': '/ˈkuːlənt θruː ˈspɪndl/', 'pos': 'n', 'meaning_vi': 'dung dịch làm mát tưới nguội xuyên qua tâm trục chính và mũi khoan', 'definition': 'a high-pressure system that delivers cutting fluid directly through the center of the rotating tool to flush chips from deep holes', 'example': 'Coolant-thru-spindle blasting at one thousand PSI lubricated the carbide deep-hole drill, preventing thermal chip welding.', 'example_vi': 'Dung dịch làm mát tưới nguội xuyên trục chính xịt ở áp suất 1.000 PSI đã bôi trơn mũi khoan sâu carbide, ngăn phôi hàn dính vì nhiệt.', 'synonyms': ['high-pressure internal coolant'], 'collocations': ['drill with coolant-thru-spindle'], 'etymology': 'Coolant pumped through the tool spindle'},
        {'word': 'chip-evacuation', 'phonetic': '/ˈtʃɪp ɪˌvækjʊˈeɪʃən/', 'pos': 'n', 'meaning_vi': 'thoát phoi tiện phay tránh kẹt gãy mũi cắt', 'definition': 'the efficient clearing and removal of metallic shavings and chips away from the cutting zone during high-speed machining', 'example': 'Polished flute geometries and pressurized air blasts ensure swift chip-evacuation during aggressive aluminum pocket milling.', 'example_vi': 'Hình học rãnh thoát dao được đánh bóng và luồng khí nén áp lực đảm bảo thoát phoi nhanh chóng khi phay hốc nhôm cường độ cao.', 'synonyms': ['swarf removal'], 'collocations': ['facilitate chip-evacuation'], 'etymology': 'Evacuating metal chips from cutting zone'},
        {'word': 'tool-wear-monitoring', 'phonetic': '/ˈtuːl wɛər ˌmɒnɪtərɪŋ/', 'pos': 'n', 'meaning_vi': 'giám sát độ mòn mẻ dao cắt dựa trên công suất trục chính', 'definition': 'the continuous tracking of acoustic emissions, spindle electrical current, or cutting forces to detect dulling or fractured tooling', 'example': 'Spindle electrical power sensors enable real-time tool-wear-monitoring, automatically triggering redundant tool changeovers.', 'example_vi': 'Cảm biến công suất điện trục chính cho phép giám sát độ mòn dao theo thời gian thực, tự động kích hoạt đổi dao dự phòng.', 'synonyms': ['cutting edge degradation tracking'], 'collocations': ['implement tool-wear-monitoring'], 'etymology': 'Monitoring wear of machine tools'},
