        {'word': 'deadweight-tonnage', 'phonetic': '/ˈdɛdweɪt ˌtʌnɪdʒ/', 'pos': 'n', 'meaning_vi': 'trọng tải toàn phần đo sức chở tối đa của tàu (DWT)', 'definition': 'a measure of how much weight a ship can carry, including cargo, fuel, fresh water, ballast water, provisions, passengers, and crew', 'example': 'Capesize bulk carriers with three hundred thousand deadweight-tonnage haul iron ore from Australia to Asian steel mills.', 'example_vi': 'Các tàu chở hàng rời cỡ Capesize với trọng tải toàn phần 300.000 DWT chuyên chở quặng sắt từ Australia đến các nhà máy thép châu Á.', 'synonyms': ['DWT carrying capacity'], 'collocations': ['exceed deadweight-tonnage'], 'etymology': 'Total weight cargo can load until dead/limit'},
        {'word': 'gross-tonnage', 'phonetic': '/ˈɡroʊs ˌtʌnɪdʒ/', 'pos': 'n', 'meaning_vi': 'dung tích toàn phần đo tổng thể tích không gian khép kín của tàu (GT)', 'definition': "a nonlinear measure of a ship's overall internal volume from keel to funnel, used for port dues and manning regulations", 'example': "Port pilotage tariffs and canal transit fees are calculated proportionally based on the ship's certified gross-tonnage.", 'example_vi': 'Biểu phí hoa tiêu cảng và phí quá cảnh kênh đào được tính toán theo tỷ lệ dựa trên dung tích toàn phần đã được chứng nhận của tàu.', 'synonyms': ['GT volumetric capacity'], 'collocations': ['certify gross-tonnage'], 'etymology': 'Total gross internal enclosure volume'},
        {'word': 'bunker-fuel', 'phonetic': '/ˈbʌŋkər fjuːəl/', 'pos': 'n', 'meaning_vi': 'nhiên liệu dầu đốt cho động cơ tàu thủy', 'definition': 'heavy fuel oil or marine gas oil used to power ship engines, traditionally stored in specialized hull bunker tanks', 'example': 'Ships sailing into emission control areas must switch from high-sulfur heavy bunker-fuel to low-sulfur marine gas oil.', 'example_vi': 'Tàu thuyền di chuyển vào các khu vực kiểm soát khí thải phải chuyển đổi từ dầu đốt tàu biển nặng có hàm lượng lưu huỳnh cao sang dầu nhẹ.', 'synonyms': ['marine fuel oil'], 'collocations': ['take on bunker-fuel'], 'etymology': 'Fuel stored in ship bunkers'},
        {'word': 'ballast-water-management', 'phonetic': '/ˈbæləst ˈwɔːtər ˌmænɪdʒmənt/', 'pos': 'n', 'meaning_vi': 'quản lý nước dằn tàu ngăn ngừa phát tán sinh vật ngoại lai', 'definition': 'procedures and technologies used to treat and neutralize ballast water pumped into empty cargo holds to prevent biological invasions', 'example': 'The international convention mandates onboard UV ballast-water-management systems to sterilize invasive aquatic microorganisms.', 'example_vi': 'Công ước quốc tế bắt buộc các hệ thống quản lý nước dằn tàu bằng tia cực tím trên tàu để khử trùng các vi sinh vật thủy sinh xâm lấn.', 'synonyms': ['BWM treatment system'], 'collocations': ['comply with ballast-water-management'], 'etymology': 'Managing ballast water treatments'},
        {'word': 'draft-survey', 'phonetic': '/ˈdrɑːft ˌsɜːrveɪ/', 'pos': 'n', 'meaning_vi': 'giám định mớn nước để xác định khối lượng hàng rời xếp dỡ', 'definition': 'a calculation of the weight of cargo loaded or unloaded to or from a ship, derived by measuring changes in vessel draft displacement', 'example': 'Marine surveyors conducted a pre-loading draft-survey, reading the forward, midship, and aft waterlines against the hull marks.', 'example_vi': 'Các giám định viên hàng hải đã tiến hành đo mớn nước trước khi xếp hàng, đọc các mực nước mũi, giữa và lái trên vạch mớn nước thân tàu.', 'synonyms': ['displacement weight survey'], 'collocations': ['conduct a draft-survey'], 'etymology': 'Surveying vessel waterline draft'},
        {'word': 'plimsoll-line', 'phonetic': '/ˈplɪmsɒl laɪn/', 'pos': 'n', 'meaning_vi': 'vạch mớn nước an toàn Plimsoll sơn trên mạn tàu', 'definition': "a reference mark located on a ship's hull that indicates the maximum legal depth to which the vessel may be safely loaded in various water types", 'example': 'Maritime safety inspectors confirmed that loading ceased before the seawater submerged the summer freshwater Plimsoll-line.', 'example_vi': 'Thanh tra an toàn hàng hải đã xác nhận việc xếp hàng dừng lại trước khi nước biển nhấn chìm vạch mớn nước mùa hè an toàn Plimsoll.', 'synonyms': ['load line mark'], 'collocations': ['load down to Plimsoll-line'], 'etymology': 'Named after reformer Samuel Plimsoll'},
        {'word': 'ship-to-shore-gantry-crane', 'phonetic': '/ˈʃɪp tə ˈʃɔːr ˈɡæntri kreɪn/', 'pos': 'n', 'meaning_vi': 'cẩu giàn STS bốc dỡ container từ tàu lên bờ bến cảng', 'definition': 'a specialized dockside portal crane used at container terminals for loading and unloading intermodal containers from container ships', 'example': 'Megamax ship-to-shore-gantry-cranes with twenty-four-container outreaches swiftly unloaded the twin forty-foot boxes.', 'example_vi': 'Các cần cẩu giàn STS cỡ Megamax có tầm vươn 24 hàng container đã bốc dỡ nhanh chóng các hộp container đôi 40 foot.', 'synonyms': ['STS quay crane'], 'collocations': ['operate ship-to-shore-gantry-cranes'], 'etymology': 'Gantry crane from ship to shore'},
