        {'word': 'breakbulk-cargo', 'phonetic': '/ˈbreɪkbʌlk ˈkɑːrɡoʊ/', 'pos': 'n', 'meaning_vi': 'hàng bách hóa rời không đóng trong container (thùng gỗ, bao tải, cuộn thép)', 'definition': 'goods that must be loaded individually, and not in intermodal containers nor in bulk as with oil or grain', 'example': 'Heavy-lift derricks hoisted steel coils and locomotives classified as breakbulk-cargo directly into the tween deck.', 'example_vi': 'Các cần cẩu tải trọng nặng đã nâng các cuộn thép và đầu máy xe lửa được phân loại là hàng bách hóa rời trực tiếp vào boong giữa.', 'synonyms': ['non-containerized general cargo'], 'collocations': ['handle breakbulk-cargo'], 'etymology': 'Cargo broken into individual bulk pieces'},
        {'word': 'dry-bulk-carrier', 'phonetic': '/ˈdraɪ bʌlk ˌkæriər/', 'pos': 'n', 'meaning_vi': 'tàu chở hàng khô rời (quặng, than đá, ngũ cốc, xi măng)', 'definition': 'a merchant ship specially designed to transport unpackaged bulk cargo such as grains, coal, ore, steel coils, and cement in its cargo holds', 'example': 'The gearless dry-bulk-carrier moored at the specialized conveyor terminal to load seventy thousand metric tons of wheat.', 'example_vi': 'Tàu chở hàng khô rời không cần cẩu đã cập cảng băng chuyền chuyên dụng để bốc 70.000 tấn ngũ cốc lúa mì.', 'synonyms': ['bulker'], 'collocations': ['charter a dry-bulk-carrier'], 'etymology': 'Carrier carrying unpackaged dry bulk'},
