        {'word': 'roll-on-roll-off', 'phonetic': '/ˈroʊl ɒn ˈroʊl ɒf/', 'pos': 'n', 'meaning_vi': 'tàu Ro-Ro chuyên chở xe cơ giới tự lăn bánh lên xuống qua cầu dẫn', 'definition': 'vessels designed to carry wheeled cargo, such as cars, trucks, semi-trailer trucks, trailers, and railroad cars', 'example': 'Automobile manufacturers charter massive multi-deck roll-on-roll-off vessels capable of transporting eight thousand electric cars across oceans.', 'example_vi': 'Các hãng sản xuất ô tô thuê các tàu Ro-Ro nhiều boong khổng lồ có khả năng vận chuyển 8.000 xe ô tô điện vượt đại dương.', 'synonyms': ['Ro-Ro vessel'], 'collocations': ['board a roll-on-roll-off vessel'], 'etymology': 'Cargo rolls on and rolls off'},
        {'word': 'pilotage', 'phonetic': '/ˈpaɪlətɪdʒ/', 'pos': 'n', 'meaning_vi': 'dịch vụ hoa tiêu dẫn đường lai dắt tàu ra vào luồng lạch cảng', 'definition': 'the act of assisting the master of a ship in navigation when entering or leaving a port, or navigating through hazardous coastal waters', 'example': 'Compulsory pilotage laws require local licensed harbor pilots to board incoming container mega-ships outside the harbor breakwater.', 'example_vi': 'Luật hoa tiêu bắt buộc yêu cầu hoa tiêu cảng có chứng chỉ tại địa phương phải lên các siêu tàu container bên ngoài đê chắn sóng của cảng.', 'synonyms': ['maritime navigation guidance'], 'collocations': ['require compulsory pilotage'], 'etymology': 'Service conducted by marine pilots'},
        {'word': 'tugboat-assistance', 'phonetic': '/ˈtʌɡboʊt əˌsɪstəns/', 'pos': 'n', 'meaning_vi': 'dịch vụ tàu lai kéo dắt hỗ trợ cập cầu cập luồng', 'definition': 'the use of powerful small boats designed to push or pull large vessels during maneuvering, docking, and undocking in tight berths', 'example': 'Three azimuth stern drive tugs provided tugboat-assistance to nudge the thirty-story cruise ship flush against the concrete wharf.', 'example_vi': 'Ba tàu kéo bánh lái đa hướng đã cung cấp dịch vụ lai dắt để đẩy con tàu du lịch 30 tầng áp sát vào bến cảng bê tông.', 'synonyms': ['tug escort service'], 'collocations': ['request tugboat-assistance'], 'etymology': 'Assistance provided by tugboats'},
        {'word': 'berth-allocation', 'phonetic': '/ˈbɜːrθ ˌæləˈkeɪʃən/', 'pos': 'n', 'meaning_vi': 'phân bổ cầu bến cập tàu tối ưu hóa thời gian chờ đợi', 'definition': 'the scheduling process at a marine terminal of assigning arriving vessels to specific quay berths and time slots', 'example': 'Dynamic berth-allocation algorithms minimized anchorage wait times by matching vessel draft with deepwater quay availability.', 'example_vi': 'Các thuật toán phân bổ cầu bến linh hoạt đã giảm thiểu thời gian tàu chờ tại khu neo đậu bằng cách khớp mớn nước với độ sâu luồng bến.', 'synonyms': ['berth assignment planning'], 'collocations': ['optimize berth-allocation'], 'etymology': 'Allocating quay berths to ships'},
        {'word': 'quay-crane-scheduling', 'phonetic': '/ˈkiː kreɪn ˌskɛdʒʊlɪŋ/', 'pos': 'n', 'meaning_vi': 'lập kế hoạch phân bổ cần cẩu bến bốc dỡ container', 'definition': 'the operational problem of assigning and sequencing quay cranes to the cargo bays of berthed container ships to minimize turnaround time', 'example': 'Port planners used mathematical optimization for quay-crane-scheduling, deploying five STS cranes per vessel simultaneously.', 'example_vi': 'Các nhà hoạch định cảng đã sử dụng phương pháp tối ưu hóa toán học cho việc lập lịch cẩu bến, bố trí 5 cẩu STS hoạt động đồng thời trên mỗi tàu.', 'synonyms': ['STS crane sequencing'], 'collocations': ['solve quay-crane-scheduling'], 'etymology': 'Scheduling operations of quay cranes'},
        {'word': 'container-stowage-plan', 'phonetic': '/kənˈteɪnər ˈstoʊɪdʒ plæn/', 'pos': 'n', 'meaning_vi': 'sơ đồ xếp đặt vị trí container trên tàu đảm bảo ổn định và an toàn', 'definition': 'a comprehensive diagram showing the precise bay-row-tier slot assigned to every container on a ship to balance vessel stability', 'example': 'Chief mates review the container-stowage-plan to verify that hazardous materials are separated and reefer boxes have power access.', 'example_vi': 'Các đại phó xem xét sơ đồ xếp dỡ container để xác minh các hóa chất nguy hiểm được cách ly và thùng lạnh có nguồn điện.', 'synonyms': ['bay plan schematic'], 'collocations': ['draft container-stowage-plan'], 'etymology': 'Plan for stowing containers securely'},
        {'word': 'vessel-turnaround-time', 'phonetic': '/ˈvɛsl ˈtɜːrnəraʊnd taɪm/', 'pos': 'n', 'meaning_vi': 'thời gian quay vòng giải phóng tàu tại cảng', 'definition': 'the total elapsed time from when a ship docks at a port until it finishes cargo operations and departs out to sea', 'example': 'State-of-the-art automated terminals slashed vessel-turnaround-time to under twenty-four hours for twenty-thousand-TEU giants.', 'example_vi': 'Các cảng tự động hóa hiện đại bậc nhất đã cắt giảm thời gian giải phóng quay vòng tàu xuống dưới 24 giờ cho các siêu tàu 20.000 TEU.', 'synonyms': ['port stay duration'], 'collocations': ['minimize vessel-turnaround-time'], 'etymology': 'Time required to turn a vessel around'},
        {'word': 'cabotage-laws', 'phonetic': '/ˈkæbətɪdʒ lɔːz/', 'pos': 'n', 'meaning_vi': 'luật hạn chế vận tải nội địa chỉ dành riêng cho đội tàu mang cờ quốc gia (Jones Act)', 'definition': 'national laws restricting domestic coastal shipping between domestic ports exclusively to vessels registered, built, and crewed in that nation', 'example': 'Under strict cabotage-laws, only American-flagged and constructed vessels may transport cargo between California and Hawaii.', 'example_vi': 'Theo các luật vận tải nội địa cabotage nghiêm ngặt, chỉ tàu mang cờ và đóng tại Mỹ mới được vận chuyển hàng giữa California và Hawaii.', 'synonyms': ['domestic coastal shipping regulations'], 'collocations': ['enforce cabotage-laws'], 'etymology': 'Cabotage (coastal trading in French)'},
        {'word': 'flag-of-convenience', 'phonetic': '/ˌflæɡ əv kənˈviːniəns/', 'pos': 'n', 'meaning_vi': 'cờ thuận tiện đăng ký tàu tại quốc gia có thuế và quy định lỏng lẻo (FOC)', 'definition': "a business practice whereby a ship's owner registers a merchant ship in a ship register of a country other than that of the ship's owner", 'example': 'Shipowners frequently register their tankers under Panamanian or Liberian flags-of-convenience to benefit from lower taxes and flexible crewing.', 'example_vi': 'Các chủ tàu thường đăng ký tàu chở dầu của họ dưới cờ thuận tiện của Panama hoặc Liberia để hưởng mức thuế thấp và thủy thủ đoàn linh hoạt.', 'synonyms': ['FOC ship registry'], 'collocations': ['fly a flag-of-convenience'], 'etymology': 'Flag chosen for regulatory convenience'},
        {'word': 'general-average', 'phonetic': '/ˌdʒɛnərəl ˈævərɪdʒ/', 'pos': 'n', 'meaning_vi': 'tổn thất chung chia đều thiệt hại giữa chủ tàu và chủ hàng khi gặp nạn biển', 'definition': 'a legal principle of maritime law according to which all cargo stakeholders proportionately share any sacrifice voluntarily made to save the ship', 'example': 'When the captain jettisoned four hundred containers to refloat the grounded freighter, he formally declared general-average.', 'example_vi': 'Khi thuyền trưởng vứt bỏ 400 container xuống biển để làm nổi lại con tàu chở hàng bị mắc cạn, ông đã chính thức tuyên bố tổn thất chung.', 'synonyms': ['shared maritime sacrifice'], 'collocations': ['declare general-average'], 'etymology': 'Average (damage/loss in maritime law)'},
        {'word': 'maritime-lien', 'phonetic': '/ˈmærɪtaɪm liːn/', 'pos': 'n', 'meaning_vi': 'quyền cầm giữ hàng hải đối với thân tàu để đòi nợ bảo dưỡng hoặc lai dắt', 'definition': 'a privileged claim upon marine property (such as a ship) for services rendered to it or damage done by it, enforceable by arrest of the ship', 'example': 'Unpaid bunker suppliers secured a court maritime-lien, instructing marshals to arrest the container vessel at anchor.', 'example_vi': 'Các nhà cung cấp nhiên liệu chưa được thanh toán đã xin được lệnh cầm giữ hàng hải từ tòa án, chỉ đạo cảnh sát bắt giữ tàu container đang neo đậu.', 'synonyms': ['vessel arrest claim'], 'collocations': ['enforce a maritime-lien'], 'etymology': 'Lien held over maritime property'},
        {'word': 'freeboard', 'phonetic': '/ˈfriːbɔːrd/', 'pos': 'n', 'meaning_vi': 'chiều cao mạn khô từ mực nước đến mép boong trên cùng', 'definition': "the vertical distance between the waterline and the upper deck level, measured at the lowest point along the ship's length", 'example': 'Sufficient freeboard ensures that ocean waves do not swamp the main cargo deck during heavy Atlantic storm swells.', 'example_vi': 'Chiều cao mạn khô đầy đủ đảm bảo sóng đại dương không tràn ngập boong hàng chính trong các đợt sóng bão dữ dội ở Đại Tây Dương.', 'synonyms': ['hull reserve buoyancy height'], 'collocations': ['measure vessel freeboard'], 'etymology': 'Board of hull that is free above water'},
        {'word': 'keel-clearance', 'phonetic': '/ˈkiːl ˌklɪərəns/', 'pos': 'n', 'meaning_vi': 'độ sâu dự phòng an toàn dưới sống đáy tàu và đáy luồng hàng hải (UKC)', 'definition': "the vertical distance between the deepest point of a ship's keel and the seabed beneath it (under-keel clearance)", 'example': 'Harbor authorities require a minimum two-meter under-keel-clearance before permitting fully laden tankers to enter shallow dredged channels.', 'example_vi': 'Nhà chức trách cảng yêu cầu độ dự phòng dưới sống đáy tàu tối thiểu 2 mét trước khi cho phép các tàu bồn đầy tải đi vào luồng nạo vét nông.', 'synonyms': ['UKC safety margin'], 'collocations': ['maintain under-keel-clearance'], 'etymology': "Clearance underneath the ship's keel"},
        {'word': 'intermodal-freight', 'phonetic': '/ˌɪntərˈmoʊdl freɪt/', 'pos': 'n', 'meaning_vi': 'vận tải hàng hóa đa phương thức kết hợp tàu biển, đường sắt và xe tải', 'definition': 'the transportation of freight in an intermodal container or vehicle, using multiple modes of transportation without cargo handling itself', 'example': 'Intermodal-freight corridors allow cargo arriving by ship at West Coast ports to cross the continent by double-stack train within four days.', 'example_vi': 'Các hành lang vận tải đa phương thức cho phép hàng hóa cập cảng Bờ Tây bằng tàu biển được vận chuyển xuyên lục địa bằng tàu hỏa hai tầng trong 4 ngày.', 'synonyms': ['multimodal container transport'], 'collocations': ['ship via intermodal-freight'], 'etymology': 'Freight moving across multiple modes'},
        {'word': 'customs-clearance-brokerage', 'phonetic': '/ˈkʌstəmz ˈklɪərəns ˈbroʊkərɪdʒ/', 'pos': 'n', 'meaning_vi': 'dịch vụ môi giới thủ tục hải quan thông quan hàng hóa xuất nhập khẩu', 'definition': 'the profession involving preparation and submission of import documentation required to facilitate export and imports through customs', 'example': 'Importers hired an experienced customs-clearance-brokerage to classify complex electronic components and remit exact tariff duties.', 'example_vi': 'Các nhà nhập khẩu đã thuê một công ty môi giới thủ tục hải quan giàu kinh nghiệm để phân loại linh kiện điện tử phức tạp và nộp đúng thuế quan.', 'synonyms': ['customs brokerage firm'], 'collocations': ['engage customs-clearance-brokerage'], 'etymology': 'Brokerage clearing goods through customs'},
        {'word': 'bonded-warehouse', 'phonetic': '/ˌbɒndɪd ˈwɛərhaʊs/', 'pos': 'n', 'meaning_vi': 'kho ngoại quan lưu trữ hàng chưa nộp thuế nhập khẩu', 'definition': 'a customs-controlled warehouse where imported dutiable goods may be stored, manipulated, or undergo operations without payment of duty', 'example': 'Importers stored luxury watches in a bonded-warehouse until foreign buyers finalized payment, deferring high import tariffs legally.', 'example_vi': 'Các nhà nhập khẩu đã lưu trữ đồng hồ xa xỉ trong kho ngoại quan cho đến khi người mua nước ngoài thanh toán xong, hoãn nộp thuế nhập khẩu hợp pháp.', 'synonyms': ['customs-supervised warehouse'], 'collocations': ['store in a bonded-warehouse'], 'etymology': 'Warehouse secured under customs bond'},
        {'word': 'cabotage-rights', 'phonetic': '/ˈkæbətɪdʒ raɪts/', 'pos': 'n', 'meaning_vi': 'quyền khai thác vận tải nội địa dọc bờ biển', 'definition': 'the legal right granted to an air or maritime carrier to transport passengers or cargo between two domestic ports within a sovereign country', 'example': 'Foreign shipping lines lobbied maritime authorities to grant temporary cabotage-rights for transporting empty feeder containers domestically.', 'example_vi': 'Các hãng tàu nước ngoài đã vận động các cơ quan hàng hải cấp quyền vận tải nội địa tạm thời để vận chuyển vỏ container rỗng trong nước.', 'synonyms': ['coastal trade privileges'], 'collocations': ['grant cabotage-rights'], 'etymology': 'Rights to conduct coastal cabotage'},
        {'word': 'container-depot', 'phonetic': '/kənˈteɪnər ˈdiːpoʊ/', 'pos': 'n', 'meaning_vi': 'bãi cất trữ và sửa chữa vỏ container rỗng (Depot)', 'definition': 'a dedicated designated off-dock facility used for the storage, maintenance, inspection, and repair of empty intermodal shipping containers', 'example': 'Haulers dropped off empty refrigerated boxes at the inland container-depot for high-pressure washing and pre-trip mechanical testing.', 'example_vi': 'Các tài xế xe kéo đã trả vỏ container lạnh rỗng tại bãi depot sâu trong đất liền để rửa bằng nước áp lực và kiểm tra kỹ thuật trước chuyến đi.', 'synonyms': ['empty box yard'], 'collocations': ['return to container-depot'], 'etymology': 'Depot holding shipping containers'},
        {'word': 'drayage', 'phonetic': '/ˈdreɪɪdʒ/', 'pos': 'n', 'meaning_vi': 'dịch vụ vận chuyển container cự ly ngắn bằng xe đầu kéo giữa cảng và kho', 'definition': 'the transport of goods or intermodal shipping containers over short distances, typically between an ocean port and a rail ramp or warehouse', 'example': 'Port bottlenecks triggered a severe shortage of drayage drivers, leaving containers stranded at terminal terminals for weeks.', 'example_vi': 'Sự tắc nghẽn cảng đã gây ra tình trạng thiếu hụt tài xế xe kéo drayage cự ly ngắn nghiêm trọng, khiến container mắc kẹt tại bến nhiều tuần.', 'synonyms': ['short-haul trucking'], 'collocations': ['hire drayage carriers'], 'etymology': 'Dray (low cart for hauling loads)'},
        {'word': 'cross-docking', 'phonetic': '/ˈkrɒs ˌdɒkɪŋ/', 'pos': 'n', 'meaning_vi': 'nghiệp vụ sang hàng trực tiếp từ xe này sang xe khác không lưu kho', 'definition': 'a logistics practice where cargo from an incoming truck or rail car is loaded directly onto outbound transport with little or no storage between', 'example': 'Retail distribution centers use cross-docking to break inbound maritime container freight into store-specific delivery trucks immediately.', 'example_vi': 'Các trung tâm phân phối bán lẻ sử dụng kỹ thuật sang hàng trực tiếp cross-docking để chia hàng container đường biển vào ngay xe giao hàng đến từng tiệm.', 'synonyms': ['direct transshipment flow'], 'collocations': ['implement cross-docking'], 'etymology': 'Docking cargo across inbound to outbound'},
        {'word': 'automated-stacking-crane', 'phonetic': '/ˈɔːtəmeɪtɪd ˈstækɪŋ kreɪn/', 'pos': 'n', 'meaning_vi': 'cần cẩu xếp container tự động trong bãi cảng (ASC)', 'definition': 'an unmanned rail-mounted gantry crane operating on software instructions to stack containers densely within yard blocks', 'example': 'Unmanned automated-stacking-cranes worked around the clock in the dark, organizing container rows for morning truck pickups.', 'example_vi': 'Các cẩu xếp container tự động không người lái ASC đã hoạt động suốt đêm trong bóng tối, sắp xếp các hàng container cho xe tải đón vào sáng hôm sau.', 'synonyms': ['ASC robotic yard gantry'], 'collocations': ['install automated-stacking-cranes'], 'etymology': 'Crane stacking boxes automatically'},
        {'word': 'terminal-operating-system', 'phonetic': '/ˈtɜːrmɪnl ˈɒpəreɪtɪŋ ˌsɪstəm/', 'pos': 'n', 'meaning_vi': 'hệ thống điều hành khai thác cảng quản lý luân chuyển hàng (TOS)', 'definition': 'a specialized software solution that manages the movement and storage of various types of cargo in and around a container terminal', 'example': 'The terminal-operating-system synchronized gate appointments with quay crane moves to eliminate gate traffic gridlocks.', 'example_vi': 'Hệ thống điều hành khai thác cảng TOS đã đồng bộ hóa lịch hẹn cổng với các chuyển động của cẩu bến để loại bỏ ùn tắc giao thông ở cổng cảng.', 'synonyms': ['TOS software engine'], 'collocations': ['upgrade terminal-operating-system'], 'etymology': 'Operating system for marine terminals'},
        {'word': 'stevedoring', 'phonetic': '/ˈstiːvədɔːrɪŋ/', 'pos': 'n', 'meaning_vi': 'nghiệp vụ bốc xếp hàng hóa lên xuống tàu biển', 'definition': 'the manual and mechanical act of loading, stowing, securing, or unloading cargo onto and off commercial ships', 'example': 'Longshoremen unions negotiate safety rules and hourly wage structures governing dockside stevedoring operations.', 'example_vi': 'Các nghiệp đoàn công nhân bốc xếp đàm phán các quy tắc an toàn và cơ cấu lương theo giờ điều chỉnh các hoạt động bốc xếp tại bến.', 'synonyms': ['dock cargo handling'], 'collocations': ['contract for stevedoring'], 'etymology': 'Estivador (stower/packer in Spanish)'},
        {'word': 'ship-chandler', 'phonetic': '/ˈʃɪp ˌtʃɑːndlər/', 'pos': 'n', 'meaning_vi': 'người cung ứng nhu yếu phẩm và trang thiết bị cho tàu biển cập cảng', 'definition': 'a specialized merchant who supplies ships with required items including foodstuffs, ropes, deck paint, engine grease, and safety equipment', 'example': 'Before the ocean crossing, the ship-chandler loaded ten tons of frozen beef, fresh cabbage, and spare hydraulic filters.', 'example_vi': 'Trước chuyến vượt đại dương, nhà cung ứng tàu biển đã đưa lên tàu 10 tấn thịt bò đông lạnh, bắp cải tươi và các bộ lọc thủy lực dự phòng.', 'synonyms': ['marine provisioner'], 'collocations': ['order from a ship-chandler'], 'etymology': 'Chandler (dealer in provisions/candles)'},
        {'word': 'bunkering-barge', 'phonetic': '/ˈbʌŋkərɪŋ bɑːrdʒ/', 'pos': 'n', 'meaning_vi': 'sà lan cấp nhiên liệu dầu đốt áp mạn tàu mẹ', 'definition': "a specialized marine tanker barge designed to transfer fuel oil and lubricants directly into a ship's bunker tanks while at anchor", 'example': 'A double-hulled bunkering-barge moored alongside the giant container vessel to pump three thousand metric tons of marine fuel.', 'example_vi': 'Một sà lan cấp dầu hai lớp vỏ đã áp mạn con tàu container khổng lồ để bơm 3.000 tấn nhiên liệu đốt hàng hải.', 'synonyms': ['fuel supply tanker barge'], 'collocations': ['dispatch a bunkering-barge'], 'etymology': 'Barge delivering ship bunkers'},
        {'word': 'cold-ironing', 'phonetic': '/ˈkoʊld ˌaɪərnɪŋ/', 'pos': 'n', 'meaning_vi': 'tiếp điện từ bờ cho tàu cập bến để tắt hoàn toàn động cơ phát điện (Shore Power)', 'definition': 'the process of providing shoreside electrical power to a ship at berth while its main and auxiliary engines are turned off, cutting emissions', 'example': 'Port environmental ordinances mandate cold-ironing for berthed cruise ships to eliminate diesel smoke pollution over coastal cities.', 'example_vi': 'Các sắc lệnh môi trường cảng bắt buộc tiếp điện từ bờ cho các tàu du lịch cập bến để loại bỏ khói dầu diesel gây ô nhiễm thành phố ven biển.', 'synonyms': ['alternative maritime power (AMP)'], 'collocations': ['connect to cold-ironing'], 'etymology': 'Turning iron engines cold at berth'},
        {'word': 'anchorage-zone', 'phonetic': '/ˈæŋkərɪdʒ zoʊn/', 'pos': 'n', 'meaning_vi': 'khu vực neo đậu tàu ngoài khơi chờ lệnh vào cảng', 'definition': 'a designated area of sea where ships may safely drop anchor while waiting for a berth, quarantine inspection, or pilot boarding', 'example': 'Dozens of bulk carriers lay at anchor within the outer anchorage-zone, waiting for river tide levels to rise.', 'example_vi': 'Hàng chục tàu chở hàng rời nằm thả neo trong khu vực neo đậu ngoài khơi, chờ mực nước thủy triều trên sông dâng cao.', 'synonyms': ['vessel waiting roadstead'], 'collocations': ['anchor in the anchorage-zone'], 'etymology': 'Zone designated for dropping anchor'},
        {'word': 'fairway-channel', 'phonetic': '/ˈfɛərweɪ ˌtʃænl/', 'pos': 'n', 'meaning_vi': 'luồng hàng hải chính an toàn cho tàu bè lưu thông ra vào cảng', 'definition': 'the navigable part of a waterway, harbor, or river that is kept dredged and marked with buoys for safe commercial vessel passage', 'example': 'Dredgers worked around the clock deepening the primary fairway-channel to sixteen meters to accommodate Post-Panamax ships.', 'example_vi': 'Tàu hút bùn làm việc ngày đêm nạo vét luồng hàng hải chính sâu tới 16 mét để tiếp nhận các tàu cỡ Post-Panamax.', 'synonyms': ['navigable shipping corridor'], 'collocations': ['dredge the fairway-channel'], 'etymology': 'Way that is fair/navigable for ships'},
        {'word': 'dredging-operation', 'phonetic': '/ˈdrɛdʒɪŋ ˌɒpəˈreɪʃən/', 'pos': 'n', 'meaning_vi': 'hoạt động nạo vét bùn đất khơi thông luồng cảng', 'definition': 'the excavation of sediment and debris from the bottom of lakes, rivers, harbors, and waterways to maintain required water depth', 'example': 'Environmental agencies monitored the harbor dredging-operation to prevent heavy metal silt plumes from dispersing across fisheries.', 'example_vi': 'Các cơ quan môi trường đã giám sát hoạt động nạo vét cảng để ngăn chặn các luồng bùn chứa kim loại nặng phát tán qua các ngư trường.', 'synonyms': ['channel deepening project'], 'collocations': ['execute a dredging-operation'], 'etymology': 'Operation dredging channel beds'},
        {'word': 'fender-system', 'phonetic': '/ˈfɛndər ˌsɪstəm/', 'pos': 'n', 'meaning_vi': 'hệ thống đệm va cao su bến cảng chống va đập thân tàu', 'definition': 'protective bumpers made of reinforced rubber or polyurethane mounted along quay walls to absorb ship kinetic impact during docking', 'example': 'Heavy cone-type rubber fender-systems absorbed thousands of foot-tons of kinetic energy as the laden vessel touched the pier.', 'example_vi': 'Hệ thống đệm va cao su hình nón nặng nề đã hấp thụ hàng nghìn foot-tấn động năng khi con tàu đầy tải chạm vào cầu cảng.', 'synonyms': ['dock protective bumper'], 'collocations': ['install a fender-system'], 'etymology': 'System fending off hull impact'},
        {'word': 'bollard-pull', 'phonetic': '/ˈbɒlərd pʊl/', 'pos': 'n', 'meaning_vi': 'sức kéo đo bằng tấn của cọc bích hoặc tàu kéo', 'definition': 'a conventional measure of the pulling force exerted by a watercraft, such as a tugboat, on a stationary shore towing bollard', 'example': 'The offshore salvage tug boasts an impressive two-hundred-ton bollard-pull, capable of refloating stranded supertankers.', 'example_vi': 'Tàu kéo cứu hộ ngoài khơi sở hữu sức kéo cọc bích ấn tượng tới 200 tấn, có khả năng làm nổi lại các siêu tàu chở dầu mắc cạn.', 'synonyms': ['towing tension metric'], 'collocations': ['rated for eighty-ton bollard-pull'], 'etymology': 'Pull exerted on a dock bollard'},
        {'word': 'mooring-winch', 'phonetic': '/ˈmʊərɪŋ wɪntʃ/', 'pos': 'n', 'meaning_vi': 'tời cáp buộc tàu giữ tàu cố định vào cầu cảng', 'definition': 'a piece of mechanical machinery used to secure a ship to a wharf or pier by pulling and tensioning heavy synthetic mooring lines', 'example': 'Automated tensioning mooring-winches continuously adjust wire line tension to compensate for tidal elevation swings.', 'example_vi': 'Các tời buộc tàu chỉnh sức căng tự động liên tục điều chỉnh độ căng của dây cáp để bù đắp cho sự lên xuống của thủy triều.', 'synonyms': ['berthing rope windlass'], 'collocations': ['secure mooring-winches'], 'etymology': 'Winch holding mooring hawsers'},
        {'word': 'flotsam-and-jetsam', 'phonetic': '/ˈflɒtsəm ənd ˈdʒɛtsəm/', 'pos': 'n', 'meaning_vi': 'mảnh vỡ trôi nổi tự nhiên và hàng hóa chủ động vứt bỏ khi tàu gặp nạn', 'definition': 'flotsam is wreckage found floating on the sea; jetsam is cargo that was deliberately thrown overboard to lighten a ship in distress', 'example': 'Coast guard patrol cutters logged flotsam-and-jetsam, consisting of wooden pallets and sealed oil drums, drifting three miles offshore.', 'example_vi': 'Các tàu tuần tra cảnh sát biển đã ghi nhận mảnh vỡ trôi nổi và hàng hóa vứt bỏ gồm các pallet gỗ và thùng dầu niêm phong dạt cách bờ 3 dặm.', 'synonyms': ['floating marine debris'], 'collocations': ['identify flotsam-and-jetsam'], 'etymology': 'Flotsam floats; jetsam is jettisoned'},
        {'word': 'drydocking', 'phonetic': '/ˈdraɪˌdɒkɪŋ/', 'pos': 'n', 'meaning_vi': 'hoạt động đưa tàu lên ụ khô để bảo dưỡng và sơn cạo hà đáy tàu', 'definition': 'the process of bringing a ship into a dry dock, draining the water, and exposing the hull below the waterline for repairs and recoating', 'example': 'Every five years, commercial cargo vessels must undergo mandatory drydocking for hull ultrasonic thickness inspections.', 'example_vi': 'Cứ sau mỗi 5 năm, các tàu chở hàng thương mại phải trải qua đợt lên ụ khô bắt buộc để kiểm tra siêu âm độ dày thân vỏ.', 'synonyms': ['vessel drydock overhaul'], 'collocations': ['schedule drydocking'], 'etymology': 'Docking in a dried basin'},
        {'word': 'antifouling-paint', 'phonetic': '/ˌæntiˈfaʊlɪŋ peɪnt/', 'pos': 'n', 'meaning_vi': 'sơn chống hà hà bám đáy tàu bảo vệ thân vỏ', 'definition': 'a specialized coating applied to the hull of a ship to slow the growth of subaquatic organisms such as barnacles and algae', 'example': 'Applying copper-free silicone antifouling-paint smoothed hull hydrodynamics, reducing vessel fuel consumption by six percent.', 'example_vi': 'Sơn lớp sơn chống hà gốc silicone không chứa đồng đã làm mượt tính thủy động lực học của thân tàu, giảm 6% mức tiêu hao nhiên liệu.', 'synonyms': ['hull biofouling coating'], 'collocations': ['coat with antifouling-paint'], 'etymology': 'Paint fighting marine hull fouling'},
        {'word': 'hull-biofouling', 'phonetic': '/hʌl ˌbaɪoʊˈfaʊlɪŋ/', 'pos': 'n', 'meaning_vi': 'sinh vật biển bám vào thân vỏ tàu làm tăng ma sát và tiêu hao nhiên liệu', 'definition': 'the accumulation of microorganisms, plants, algae, or small animals (barnacles, mussels) on underwater ship hulls', 'example': 'Severe hull-biofouling creates immense hydrodynamic drag, forcing propulsion engines to burn extra bunker oil to maintain speed.', 'example_vi': 'Sinh vật biển bám dày vào thân tàu tạo ra lực cản thủy động học khổng lồ, buộc động cơ đẩy phải đốt thêm dầu để duy trì tốc độ.', 'synonyms': ['marine organism encrustation'], 'collocations': ['clean hull-biofouling'], 'etymology': 'Biological fouling on ship hulls'},
        {'word': 'transit-time', 'phonetic': '/ˈtrænzɪt taɪm/', 'pos': 'n', 'meaning_vi': 'thời gian hành trình vận chuyển hàng hóa từ cảng đi đến cảng đích', 'definition': 'the total elapsed duration required for cargo or ships to travel from the port of origin to the final destination port', 'example': 'Slow-steaming strategies extended oceanic transit-time across the Pacific from twelve days to sixteen days to save bunker fuel.', 'example_vi': 'Chiến lược chạy chậm tiết kiệm nhiên liệu đã kéo dài thời gian vận chuyển qua Thái Bình Dương từ 12 ngày lên 16 ngày.', 'synonyms': ['shipping route duration'], 'collocations': ['reduce transit-time'], 'etymology': 'Time spent in shipping transit'},
        {'word': 'slow-steaming', 'phonetic': '/ˈsloʊ ˌstiːmɪŋ/', 'pos': 'n', 'meaning_vi': 'chạy chậm tiết kiệm nhiên liệu và giảm phát thải khí nhà kính', 'definition': 'the practice of deliberately operating cargo ships, especially container ships, at significantly lower cruising speeds to reduce fuel burn', 'example': 'Adopting slow-steaming at eighteen knots instead of twenty-four knots reduced carbon emissions by nearly thirty percent.', 'example_vi': 'Áp dụng biện pháp chạy chậm ở tốc độ 18 hải lý/giờ thay vì 24 hải lý/giờ đã cắt giảm lượng khí thải carbon gần 30%.', 'synonyms': ['eco-speed navigation'], 'collocations': ['implement slow-steaming'], 'etymology': 'Steaming at slower engine speeds'},
        {'word': 'sea-chest', 'phonetic': '/ˈsiː tʃɛst/', 'pos': 'n', 'meaning_vi': 'khoang hút nước biển làm mát động cơ và cấp nước dằn', 'definition': "an intake reservoir recessed into the ship's underwater hull, equipped with strainers to supply seawater to cooling and ballast pumps", 'example': 'Divers inspected the underwater sea-chest grates to remove accumulated plastic bags and juvenile barnacles.', 'example_vi': 'Thợ lặn đã kiểm tra các lưới chắn khoang hút nước biển dưới nước để loại bỏ túi nhựa tích tụ và hà con bám.', 'synonyms': ['hull intake suction box'], 'collocations': ['clear sea-chest strainers'], 'etymology': 'Chest recessed into hull for seawater'},
        {'word': 'bulbous-bow', 'phonetic': '/ˈbʌlbəs boʊ/', 'pos': 'n', 'meaning_vi': 'mũi quả lê nhô ra dưới ngấn nước mũi tàu giảm sóng cản', 'definition': 'a protruding bulb at the bow of a ship just below the waterline that modifies water flow, reducing drag and increasing fuel efficiency', 'example': 'The hydrodynamically optimized bulbous-bow cancels out bow wave systems, slashing fuel consumption on long ocean voyages.', 'example_vi': 'Mũi quả lê được tối ưu hóa thủy động lực học triệt tiêu các hệ sóng mũi, cắt giảm mạnh mức tiêu thụ nhiên liệu trên các hải trình dài.', 'synonyms': ['protruding bow bulb'], 'collocations': ['retrofit a bulbous-bow'], 'etymology': 'Bow shaped like a hydrodynamic bulb'},
        {'word': 'rudder-stock', 'phonetic': '/ˈrʌdər stɒk/', 'pos': 'n', 'meaning_vi': 'trục bẻ lái truyền lực từ máy lái xuống bánh lái tàu', 'definition': "the vertical shaft or post by which a ship's rudder is turned and supported, transferring torque from the steering gear", 'example': 'Marine surveyors inspected the forged steel rudder-stock for fatigue cracking during the five-year survey.', 'example_vi': 'Các giám định viên hàng hải đã kiểm tra trục bánh lái bằng thép rèn để tìm các vết nứt do mỏi trong đợt kiểm định 5 năm.', 'synonyms': ['rudder turning spindle'], 'collocations': ['inspect rudder-stock'], 'etymology': 'Stock shaft turning the rudder'},
        {'word': 'bow-thruster', 'phonetic': '/ˈbaʊ ˌθrʌstər/', 'pos': 'n', 'meaning_vi': 'chân vịt mũi tạo lực đẩy ngang hỗ trợ tàu tự điều động cập bến', 'definition': 'a transversal propulsion device built into, or mounted to, the bow of a watercraft to make it more maneuverable at low docking speeds', 'example': "The captain pulsed the electric bow-thruster to swing the freighter's bow cleanly away from the concrete pier face.", 'example_vi': 'Thuyền trưởng đã nhấp chân vịt mũi điện để xoay mũi tàu chở hàng ra khỏi mặt cầu cảng bê tông một cách gọn gàng.', 'synonyms': ['transverse maneuvering propeller'], 'collocations': ['engage bow-thruster'], 'etymology': 'Thruster located at the vessel bow'},
        {'word': 'bunkering-manifold', 'phonetic': '/ˈbʌŋkərɪŋ ˈmænɪfoʊld/', 'pos': 'n', 'meaning_vi': 'cụm họng tiếp nhiên liệu trên boong tàu nối với ống cấp dầu', 'definition': 'the deck-level connection pipe assembly with multiple valves where fuel bunkering hoses from shore or barges are attached', 'example': 'Engineers connected flexible composite fuel hoses to the bunkering-manifold under the watchful eyes of safety personnel.', 'example_vi': 'Các kỹ sư đã kết nối các ống mềm dẫn nhiên liệu composite với cụm họng tiếp dầu dưới sự giám sát chặt chẽ của nhân viên an toàn.', 'synonyms': ['fuel filling pipe station'], 'collocations': ['connect to bunkering-manifold'], 'etymology': 'Manifold for taking on bunker fuel'},
        {'word': 'spill-containment-boom', 'phonetic': '/ˈspɪl kənˌteɪnmənt buːm/', 'pos': 'n', 'meaning_vi': 'phao quây dầu tràn nổi trên mặt nước ngăn dầu loang', 'definition': 'a floating physical barrier deployed on water to enclose and prevent the spreading of oil spills during marine bunkering accidents', 'example': 'Port safety rules dictate deploying floating spill-containment-booms around any oil tanker transferring petroleum cargo.', 'example_vi': 'Quy tắc an toàn cảng quy định phải triển khai phao quây dầu tràn nổi xung quanh bất kỳ tàu chở dầu nào đang chuyển hàng xăng dầu.', 'synonyms': ['oil slick barrier'], 'collocations': ['encircle with spill-containment-booms'], 'etymology': 'Boom containing oil spills on water'},
        {'word': 'hydrostatic-release-unit', 'phonetic': '/ˌhaɪdrəˈstætɪk rɪˈliːs ˈjuːnɪt/', 'pos': 'n', 'meaning_vi': 'cơ cấu nhả thủy tĩnh tự động giải phóng phao cứu sinh khi tàu chìm (HRU)', 'definition': 'a pressure-activated mechanism designed to automatically release a liferaft canister when a sinking ship descends below four meters', 'example': 'The hydrostatic-release-unit severed the liferaft lashing rope as the vessel sank, allowing the canister to float free and inflate.', 'example_vi': 'Cơ cấu nhả thủy tĩnh đã cắt đứt dây buộc bè cứu sinh khi con tàu chìm xuống dưới 4 mét, cho phép phao nổi tự do và tự thổi phồng.', 'synonyms': ['liferaft auto-release HRU'], 'collocations': ['replace hydrostatic-release-units'], 'etymology': 'Unit releasing via water hydrostatic pressure'},
        {'word': 'vessel-traffic-service', 'phonetic': '/ˈvɛsl ˈtræfɪk ˌsɜːrvɪs/', 'pos': 'n', 'meaning_vi': 'dịch vụ điều phối giao thông tàu thuyền giám sát radar luồng cảng (VTS)', 'definition': 'a marine traffic monitoring system established by harbor or port authorities, similar to air traffic control for aircraft', 'example': 'Vessel-traffic-service radar operators radioed the approaching bulk carrier to alter course to avoid a crossing tug and tow.', 'example_vi': 'Các nhân viên radar của dịch vụ điều phối giao thông tàu biển VTS đã gọi bộ đàm cho tàu chở hàng rời đổi hướng tránh một đoàn tàu lai kéo.', 'synonyms': ['VTS harbor radar control'], 'collocations': ['contact vessel-traffic-service'], 'etymology': 'Service managing marine vessel traffic'},
        {'word': 'automatic-identification-system', 'phonetic': '/ˌɔːtəˈmætɪk aɪˌdɛntɪfɪˈkeɪʃən ˌsɪstəm/', 'pos': 'n', 'meaning_vi': 'hệ thống nhận dạng tự động phát sóng vị trí tàu qua VHF (AIS)', 'definition': 'an automated tracking system that uses transceivers on ships to broadcast vessel identification, GPS position, speed, and heading', 'example': 'Port security tracked incoming container vessels over five hundred miles out using satellite-linked automatic-identification-systems.', 'example_vi': 'An ninh cảng đã theo dõi các tàu container đang đến cách xa hơn 500 dặm bằng các hệ thống nhận dạng tự động AIS kết nối vệ tinh.', 'synonyms': ['AIS transponder tracking'], 'collocations': ['broadcast AIS data'], 'etymology': 'System identifying vessels automatically'},
        {'word': 'maritime-domain-awareness', 'phonetic': '/ˈmærɪtaɪm doʊˈmeɪn əˌwɛərnəs/', 'pos': 'n', 'meaning_vi': 'nhận thức toàn diện không gian an ninh hàng hải (MDA)', 'definition': 'the effective understanding of anything associated with the global maritime domain that could impact security, safety, or economy', 'example': 'Coast guard commanders utilized satellite radar feeds and AIS tracking to achieve total maritime-domain-awareness along the coastline.', 'example_vi': 'Các chỉ huy cảnh sát biển đã sử dụng radar vệ tinh và theo dõi AIS để đạt được nhận thức toàn diện không gian an ninh hàng hải ven bờ.', 'synonyms': ['MDA surveillance'], 'collocations': ['enhance maritime-domain-awareness'], 'etymology': 'Awareness of the whole maritime domain'},
        {'word': 'intermodal-rail-ramp', 'phonetic': '/ˌɪntərˈmoʊdl ˈreɪl ræmp/', 'pos': 'n', 'meaning_vi': 'ga đường sắt trung chuyển xếp dỡ container hai tầng (On-dock rail)', 'definition': 'a specialized railway yard directly adjacent to marine docks where containers are loaded directly onto double-stack flatcars', 'example': 'Containers discharged from the vessel were wheeled directly onto the on-dock intermodal-rail-ramp for expedited inland rail transit.', 'example_vi': 'Các container dỡ từ tàu đã được kéo trực tiếp vào ga đường sắt trung chuyển tại bến để vận chuyển nhanh bằng tàu hỏa vào nội địa.', 'synonyms': ['on-dock rail hub'], 'collocations': ['transfer at intermodal-rail-ramp'], 'etymology': 'Ramp transferring containers to rail cars'},
        {'word': 'feeder-vessel', 'phonetic': '/ˈfiːdər ˈvɛsl/', 'pos': 'n', 'meaning_vi': 'tàu trung chuyển gom hàng từ cảng phụ về cảng cửa ngõ quốc tế', 'definition': 'a small to medium-sized container ship that collects shipping containers from smaller regional ports and feeds them to central hub ports', 'example': 'A thousand-TEU feeder-vessel shuttles between regional Baltic river ports and the mega-hub container terminal in Rotterdam.', 'example_vi': 'Một con tàu trung chuyển gom hàng 1.000 TEU chạy con thoi giữa các cảng sông Baltic khu vực và cảng trung chuyển siêu lớn ở Rotterdam.', 'synonyms': ['hub-and-spoke feeder ship'], 'collocations': ['transfer to feeder-vessels'], 'etymology': 'Vessel feeding cargo to hub mother ships'},
        {'word': 'transshipment-hub', 'phonetic': '/trænzˈʃɪpmənt hʌb/', 'pos': 'n', 'meaning_vi': 'cảng trung chuyển quốc tế nơi dỡ hàng chuyển sang tàu khác', 'definition': 'a primary seaport that acts as a central distribution node, where cargo from deep-sea mother vessels is transferred onto regional feeder ships', 'example': "The Port of Singapore functions as the world's premier transshipment-hub, connecting hundreds of maritime trading lanes.", 'example_vi': 'Cảng Singapore hoạt động như một cảng trung chuyển quốc tế hàng đầu thế giới, kết nối hàng trăm tuyến thương mại hàng hải.', 'synonyms': ['marine hub terminal'], 'collocations': ['transship through a hub'], 'etymology': 'Hub for transshipping cargo'},
        {'word': 'dangerous-goods-manifest', 'phonetic': '/ˈdeɪndʒərəs ɡʊdz ˈmænɪfɛst/', 'pos': 'n', 'meaning_vi': 'bản lược khai hàng hóa nguy hiểm theo quy chuẩn quốc tế (IMDG)', 'definition': 'an official shipping document declaring hazardous materials, chemicals, explosives, or radioactive cargo onboard under IMDG rules', 'example': 'Customs officers cross-referenced the dangerous-goods-manifest to ensure lithium-ion battery containers were segregated on weather decks.', 'example_vi': 'Các cán bộ hải quan đã đối chiếu bản lược khai hàng hóa nguy hiểm để đảm bảo container pin lithium-ion được cách ly trên boong hở.', 'synonyms': ['IMDG hazardous cargo list'], 'collocations': ['certify dangerous-goods-manifest'], 'etymology': 'Manifest listing dangerous goods'},
        {'word': 'lashing-gear', 'phonetic': '/ˈlæʃɪŋ ɡɪər/', 'pos': 'n', 'meaning_vi': 'thiết bị chằng buộc cố định container chống trôi lật trên boong tàu', 'definition': 'the heavy steel rods, turnbuckles, twistlocks, and bridge fittings used to lock multi-tier container stacks rigidly to the vessel structure', 'example': 'Deckhands checked that all twistlocks and turnbuckle lashing-gear were tightened before the vessel braved rough ocean weather.', 'example_vi': 'Các thủy thủ đã kiểm tra rằng tất cả các gù khóa và tăng đơ chằng buộc thép đã được siết chặt trước khi tàu vượt qua thời tiết biển động.', 'synonyms': ['container securing hardware'], 'collocations': ['tighten lashing-gear'], 'etymology': 'Gear lashing cargo securely'},
        {'word': 'intermodal-chassis', 'phonetic': '/ˌɪntərˈmoʊdl ˈtʃæsi/', 'pos': 'n', 'meaning_vi': 'rơ-moóc chuyên dụng chở container kéo bằng xe đầu kéo', 'definition': 'a wheeled skeletal trailer specifically designed to securely transport ocean shipping containers over highways behind semi-trucks', 'example': 'The driver locked the forty-foot high-cube container onto the skeletal intermodal-chassis twistlocks before departing the terminal gate.', 'example_vi': 'Tài xế đã khóa container 40 foot cao lên các gù xoay của rơ-moóc chuyên dụng trước khi khởi hành rời cổng cảng.', 'synonyms': ['container skeletal trailer'], 'collocations': ['hitch an intermodal-chassis'], 'etymology': 'Chassis for intermodal highway trucking'},
