        {'word': 'détente', 'phonetic': '/deɪˈtɑːnt/', 'pos': 'n', 'meaning_vi': 'thời kỳ hòa hoãn giảm bớt căng thẳng địa chính trị', 'definition': 'the easing of hostility or strained relations, especially between countries, through negotiated arms limitation and dialogue', 'example': 'The signing of the Strategic Arms Limitation Talks ushered in a decade of superpower détente during the 1970s.', 'example_vi': 'Việc ký kết Đàm phán Giới hạn Vũ khí Chiến lược đã mở ra một thập kỷ hòa hoãn giữa các siêu cường trong những năm 1970.', 'synonyms': ['easing of geopolitical tension'], 'collocations': ['era of détente'], 'etymology': 'Détente (relaxation/loosening in French)'},
        {'word': 'brinkmanship', 'phonetic': '/ˈbrɪŋkmənʃɪp/', 'pos': 'n', 'meaning_vi': 'chính sách bên miệng hố chiến tranh đẩy khủng hoảng tới đỉnh điểm để ép nhượng bộ', 'definition': 'the practice of pursuing a dangerous policy to the limits of safety before stopping, especially in foreign politics', 'example': 'During the Cuban Missile Crisis, terrifying nuclear brinkmanship brought the world to the very edge of atomic war.', 'example_vi': 'Trong Cuộc khủng hoảng tên lửa Cuba, chính sách bên miệng hố chiến tranh hạt nhân đáng sợ đã đưa thế giới đến bờ vực của cuộc chiến tranh nguyên tử.', 'synonyms': ['crisis escalation gambling'], 'collocations': ['engage in high-stakes brinkmanship'], 'etymology': 'Pushing to the brink of catastrophe'},
        {'word': 'belligerent', 'phonetic': '/bɪˈlɪdʒərənt/', 'pos': 'n', 'meaning_vi': 'bên tham chiến trong một cuộc xung đột vũ trang quốc tế', 'definition': 'a nation or person engaged in war or conflict, as recognized by international humanitarian law and conventions', 'example': 'The Geneva Conventions dictate specific obligations regarding the humane treatment of prisoners captured by any belligerent.', 'example_vi': 'Các Công ước Geneva quy định các nghĩa vụ cụ thể liên quan đến việc đối xử nhân đạo với các tù binh bị bất kỳ bên tham chiến nào bắt giữ.', 'synonyms': ['warring faction/nation'], 'collocations': ['act as a declared belligerent'], 'etymology': 'Bellum (war) + gerere (to wage in Latin)'},
        {'word': 'sovereign-equality', 'phonetic': '/ˈsɒvrɪn ɪˈkwɒləti/', 'pos': 'n', 'meaning_vi': 'bình đẳng chủ quyền giữa mọi quốc gia theo hiến chương Liên Hợp Quốc', 'definition': 'the legal concept that every sovereign state possesses the same juridical rights and legal standing regardless of size or economic wealth', 'example': 'Article 2 of the United Nations Charter is founded on the foundational principle of the sovereign-equality of all its member states.', 'example_vi': 'Điều 2 của Hiến chương Liên Hợp Quốc dựa trên nguyên tắc nền tảng về quyền bình đẳng chủ quyền của tất cả các quốc gia thành viên.', 'synonyms': ['equal legal standing of states'], 'collocations': ['uphold sovereign-equality'], 'etymology': 'Equality of sovereign state jurisdictions'},
