        {'word': 'annexation', 'phonetic': '/ˌænɛkˈseɪʃən/', 'pos': 'n', 'meaning_vi': 'sáp nhập lãnh thổ chiếm đoạt bất hợp pháp của quốc gia khác', 'definition': 'the formal administrative act whereby a state proclaims its sovereignty over territory outside its domain, often by force', 'example': 'The UN General Assembly overwhelmingly passed a resolution condemning the unilateral annexation of foreign coastal provinces.', 'example_vi': 'Đại hội đồng Liên Hợp Quốc đã thông qua một nghị quyết áp đảo lên án việc sáp nhập đơn phương các tỉnh ven biển của nước ngoài.', 'synonyms': ['territorial seizure'], 'collocations': ['condemn unlawful annexation'], 'etymology': 'Annexing territory by state proclamation'},
        {'word': 'secession', 'phonetic': '/sɪˈsɛʃən/', 'pos': 'n', 'meaning_vi': 'sự ly khai tách ra để thành lập một quốc gia độc lập', 'definition': 'the withdrawal of a group from a larger entity, especially a political state, to form an independent sovereign country', 'example': 'Constitutional courts ruled that the unilateral declaration of regional secession was null, void, and unconstitutional.', 'example_vi': 'Các tòa án hiến pháp đã phán quyết rằng tuyên bố đơn phương ly khai của khu vực là vô hiệu, bất hợp pháp và vi hiến.', 'synonyms': ['breakaway independence move'], 'collocations': ['declare political secession'], 'etymology': 'Secedere (to withdraw/go apart in Latin)'},
        {'word': 'self-determination', 'phonetic': '/ˌsɛlf dɪˌtɜːrmɪˈneɪʃən/', 'pos': 'n', 'meaning_vi': 'quyền tự quyết dân tộc tự do lựa chọn thể chế chính trị', 'definition': 'the legal right of cohesive national peoples to freely choose their political status and freely pursue their economic development', 'example': 'The decolonization wave after World War II was powered by international recognition of the universal right to self-determination.', 'example_vi': 'Làn sóng phi thực dân hóa sau Chiến tranh Thế giới thứ hai được thúc đẩy bởi sự công nhận quốc tế đối với quyền tự quyết phổ quát.', 'synonyms': ['popular sovereignty right'], 'collocations': ['exercise self-determination'], 'etymology': "Determining one's own political destiny"},
        {'word': 'balkanization', 'phonetic': '/ˌbɔːlkənaɪˈzeɪʃən/', 'pos': 'n', 'meaning_vi': 'sự phân rã lãnh thổ thành các tiểu quốc thù địch xung đột lẫn nhau', 'definition': 'the fragmentation of a larger state or region into smaller, mutually hostile political units along ethnic or religious lines', 'example': 'Geopolitical observers warned that proxy interference could lead to the violent balkanization of the war-torn federation.', 'example_vi': 'Các nhà quan sát địa chính trị cảnh báo rằng sự can thiệp của các bên ủy nhiệm có thể dẫn đến sự phân rã balkanization bạo lực của liên bang.', 'synonyms': ['territorial fragmentation into rival states'], 'collocations': ['threat of balkanization'], 'etymology': 'Refers to historic Balkan regional fractures'},
        {'word': 'finlandization', 'phonetic': '/ˌfɪnləndəɪˈzeɪʃən/', 'pos': 'n', 'meaning_vi': 'chính sách Phần Lan hóa giữ trung lập tuyệt đối để xoa dịu láng giềng hùng mạnh', 'definition': 'the process by which one powerful country influences the policies of a smaller neighboring country without outright occupying it', 'example': 'During the Cold War, Helsinki pursued finlandization, preserving internal democracy while scrupulously avoiding anti-Soviet pacts.', 'example_vi': 'Trong Chiến tranh Lạnh, Helsinki theo đuổi chính sách Phần Lan hóa, giữ vững nền dân chủ trong khi né tránh các hiệp ước chống Liên Xô.', 'synonyms': ['neutral appeasement posture'], 'collocations': ['accuse of finlandization'], 'etymology': 'Neutrality modeled on post-WWII Finland'},
        {'word': 'appeasement-policy', 'phonetic': '/əˈpiːzmənt ˈpɒləsi/', 'pos': 'n', 'meaning_vi': 'chính sách nhân nhượng nhượng bộ kẻ xâm lược để cầu hòa tạm bợ', 'definition': 'a diplomatic policy of making political or material concessions to an aggressive power in order to avoid military conflict', 'example': "The 1938 Munich Agreement remains history's most tragic demonstration that an appeasement-policy only emboldens dictators.", 'example_vi': 'Hiệp định Munich năm 1938 vẫn là minh chứng bi thảm nhất trong lịch sử cho thấy chính sách nhân nhượng chỉ làm cho những kẻ độc tài thêm táo tợn.', 'synonyms': ['concessionary peace policy'], 'collocations': ['criticize an appeasement-policy'], 'etymology': 'Policy appeasing aggressive powers'},
        {'word': 'proxy-war', 'phonetic': '/ˈprɒksi wɔːr/', 'pos': 'n', 'meaning_vi': 'chiến tranh ủy nhiệm xung đột gián tiếp qua các lực lượng địa phương', 'definition': 'a war instigated by a major power that does not itself become directly involved, using third parties to fight on its behalf', 'example': 'The regional civil war rapidly degenerated into a bloody proxy-war funded, armed, and fueled by rival regional coalitions.', 'example_vi': 'Cuộc nội chiến khu vực đã nhanh chóng suy thoái thành một cuộc chiến tranh ủy nhiệm đẫm máu được tài trợ và trang bị vũ khí bởi các liên minh kình địch.', 'synonyms': ['surrogate conflict'], 'collocations': ['fight a brutal proxy-war'], 'etymology': 'War fought via surrogate proxies'},
        {'word': 'demilitarized-zone', 'phonetic': '/diːˈmɪlɪtəraɪzd zoʊn/', 'pos': 'n', 'meaning_vi': 'khu phi quân sự vùng đệm cấm bố trí quân đội và vũ khí (DMZ)', 'definition': 'an area in which treaties or agreements between nations or contending groups forbid military installations, activities, or personnel', 'example': 'The heavily fortified demilitarized-zone separates the two nations along the 38th parallel with watchtowers and barbed wire.', 'example_vi': 'Khu phi quân sự được phòng thủ kiên cố chia cắt hai quốc gia dọc theo vĩ tuyến 38 với các tháp canh và dây thép gai.', 'synonyms': ['DMZ buffer area'], 'collocations': ['patrol the demilitarized-zone'], 'etymology': 'Zone demilitarized of armed forces'},
        {'word': 'armistice-agreement', 'phonetic': '/ˈɑːrmɪstɪs əˌɡriːmənt/', 'pos': 'n', 'meaning_vi': 'hiệp định đình chiến tạm ngừng giao tranh mà không cần ký hòa ước vĩnh viễn', 'definition': 'a formal agreement of warring parties to stop fighting, effectively pausing combat operations without resolving underlying sovereignty claims', 'example': 'The 1953 armistice-agreement brought an end to open hostilities on the peninsula, leaving the nations technically in a state of war.', 'example_vi': 'Hiệp định đình chiến năm 1953 đã chấm dứt các hành động thù địch công khai trên bán đảo, khiến các quốc gia về mặt kỹ thuật vẫn trong tình trạng chiến tranh.', 'synonyms': ['ceasefire treaty'], 'collocations': ['sign an armistice-agreement'], 'etymology': 'Arma (arms) + stitium (stoppage in Latin)'},
        {'word': 'peacekeeping-forces', 'phonetic': '/ˈpiːskiːpɪŋ ˈfɔːrsɪz/', 'pos': 'n', 'meaning_vi': 'lực lượng gìn giữ hòa bình Liên Hợp Quốc mang mũ nồi xanh (Blue Helmets)', 'definition': 'military forces deployed by an international body such as the UN to maintain peace and enforce a ceasefire in a conflict zone', 'example': 'Wearing iconic blue helmets, international peacekeeping-forces patrolled the disputed valley to protect humanitarian aid convoys.', 'example_vi': 'Đội mũ nồi xanh mang tính biểu tượng, lực lượng gìn giữ hòa bình quốc tế đã tuần tra thung lũng tranh chấp để bảo vệ các đoàn xe cứu trợ nhân đạo.', 'synonyms': ['UN Blue Helmets'], 'collocations': ['deploy peacekeeping-forces'], 'etymology': 'Forces keeping peace in conflict zones'},
        {'word': 'right-of-innocent-passage', 'phonetic': '/ˌraɪt əv ˈɪnəsənt ˈpæsɪdʒ/', 'pos': 'n', 'meaning_vi': 'quyền qua lại không gây hại của tàu thuyền qua lãnh hải quốc gia', 'definition': 'a concept in the law of the sea that allows a vessel to pass through the territorial waters of another state without prejudice to peace', 'example': 'Under the UN Convention on the Law of the Sea, foreign commercial ships enjoy the customary right-of-innocent-passage through coastal seas.', 'example_vi': 'Theo Công ước Liên Hợp Quốc về Luật Biển, tàu thương mại nước ngoài được hưởng quyền qua lại không gây hại thông thường qua các vùng biển ven bờ.', 'synonyms': ['maritime harmless transit right'], 'collocations': ['exercise right-of-innocent-passage'], 'etymology': 'Right of passing innocently without harm'},
        {'word': 'exclusive-economic-zone', 'phonetic': '/ɪkˈskluːsɪv ˌiːkəˈnɒmɪk zoʊn/', 'pos': 'n', 'meaning_vi': 'vùng đặc quyền kinh tế 200 hải lý khai thác tài nguyên biển (EEZ)', 'definition': 'an area of the sea in which a sovereign state has special rights regarding the exploration and use of marine resources, extending 200 nautical miles', 'example': "Coast guard cutters intercepted illegal foreign trawlers fishing without permits inside the nation's two-hundred-mile exclusive-economic-zone.", 'example_vi': 'Các tàu tuần tra cảnh sát biển đã chặn các tàu đánh cá nước ngoài hoạt động không phép bên trong vùng đặc quyền kinh tế 200 hải lý của quốc gia.', 'synonyms': ['EEZ marine jurisdiction'], 'collocations': ['patrol the exclusive-economic-zone'], 'etymology': 'Zone of exclusive economic fishing/drilling rights'},
