        {'word': 'international-criminal-court', 'phonetic': '/ˌɪntərˈnæʃənl ˈkrɪmɪnl kɔːrt/', 'pos': 'n', 'meaning_vi': 'Tòa án Hình sự Quốc tế xét xử tội ác chiến tranh và diệt chủng (ICC)', 'definition': 'an intergovernmental organization and international tribunal in The Hague with jurisdiction to prosecute individuals for war crimes and genocide', 'example': 'The prosecutor at the International-Criminal-Court unsealed an arrest warrant charging military commanders with crimes against humanity.', 'example_vi': 'Công tố viên tại Tòa án Hình sự Quốc tế đã công bố lệnh bắt giữ cáo buộc các chỉ huy quân sự phạm tội ác chống lại loài người.', 'synonyms': ['ICC tribunal in The Hague'], 'collocations': ['prosecute at the International-Criminal-Court'], 'etymology': 'Court adjudicating international war crimes'},
        {'word': 'universal-jurisdiction', 'phonetic': '/ˌjuːnɪˈvɜːrsl ˌdʒʊərɪsˈdɪkʃən/', 'pos': 'n', 'meaning_vi': 'quyền tài phán phổ quát cho phép xét xử tội ác diệt chủng bất kể nơi xảy ra', 'definition': 'a legal principle allowing national courts to claim criminal jurisdiction over an accused person regardless of where the alleged crime was committed', 'example': 'German prosecutors applied universal-jurisdiction to try and convict a foreign torture official apprehended while traveling on vacation.', 'example_vi': 'Các công tố viên Đức đã áp dụng quyền tài phán phổ quát để xét xử và kết án một viên chức tra tấn nước ngoài bị bắt khi đi du lịch.', 'synonyms': ['extra-territorial human rights prosecution'], 'collocations': ['invoke universal-jurisdiction'], 'etymology': 'Jurisdiction applicable universally everywhere'},
