        {'word': 'escrow-account', 'phonetic': '/ˈɛskroʊ əˌkaʊnt/', 'pos': 'n', 'meaning_vi': 'tài khoản ký quỹ trung gian giữ tiền cho đến khi hoàn tất nghĩa vụ hợp đồng', 'definition': 'a financial arrangement where a third party holds and regulates payment of funds required for two parties involved in a transaction', 'example': 'The buyer deposited the ten percent acquisition earnest deposit directly into a neutral title company escrow-account.', 'example_vi': 'Bên mua đã gửi khoản tiền đặt cọc mua lại 10% trực tiếp vào tài khoản ký quỹ trung gian của công ty giấy tờ pháp lý độc lập.', 'synonyms': ['third-party trust account'], 'collocations': ['hold funds in an escrow-account'], 'etymology': 'Account holding escrow funds'},
        {'word': 'sales-pipeline', 'phonetic': '/ˈseɪlz ˌpaɪplaɪn/', 'pos': 'n', 'meaning_vi': 'phễu quy trình bán hàng theo dõi các cơ hội kinh doanh từ tiềm năng đến chốt đơn', 'definition': 'a visual representation of where prospects are in the purchasing process, from initial contact to final signed deal', 'example': 'The vice president of sales reviewed the CRM dashboard to ensure the Q4 sales-pipeline contained sufficient qualified enterprise leads.', 'example_vi': 'Phó chủ tịch kinh doanh đã xem xét bảng điều khiển CRM để đảm bảo phễu bán hàng quý 4 có đủ lượng khách hàng tiềm năng chất lượng.', 'synonyms': ['sales opportunity funnel'], 'collocations': ['manage the sales-pipeline'], 'etymology': 'Pipeline channeling sales prospects'},
        {'word': 'cold-calling', 'phonetic': '/ˈkoʊld ˌkɔːlɪŋ/', 'pos': 'n', 'meaning_vi': 'gọi điện tiếp cận chào hàng tới khách hàng tiềm năng chưa từng tương tác', 'definition': 'the solicitation of business from potential customers who have had no prior contact with the salesperson conducting the call', 'example': 'Sales development representatives set twenty demonstration meetings this week solely through disciplined enterprise cold-calling.', 'example_vi': 'Các đại diện phát triển kinh doanh đã lên lịch 20 cuộc hẹn trình diễn tuần này chỉ thông qua các cuộc gọi chào hàng trực tiếp có kỷ luật.', 'synonyms': ['outbound prospecting calls'], 'collocations': ['rely on cold-calling'], 'etymology': 'Calling cold prospective buyers'},
        {'word': 'lead-generation', 'phonetic': '/ˈliːd ˌdʒɛnəˈreɪʃən/', 'pos': 'n', 'meaning_vi': 'hoạt động tìm kiếm và thu hút khách hàng tiềm năng', 'definition': 'the initiation of consumer interest or enquiry into products or services of a business through webinars, ads, and content marketing', 'example': 'Targeted LinkedIn sponsored white papers served as the primary B2B lead-generation engine for the enterprise software firm.', 'example_vi': 'Các sách trắng được tài trợ nhắm mục tiêu trên LinkedIn đóng vai trò là động lực tạo khách hàng tiềm năng B2B chính cho công ty phần mềm.', 'synonyms': ['prospect acquisition'], 'collocations': ['accelerate lead-generation'], 'etymology': 'Generating new customer leads'},
        {'word': 'customer-acquisition-cost', 'phonetic': '/ˈkʌstəmər ˌækwɪˈzɪʃən kɒst/', 'pos': 'n', 'meaning_vi': 'chi phí thu hút một khách hàng mới (CAC)', 'definition': 'the total cost of sales and marketing efforts needed to acquire a single paying customer over a given business period', 'example': "Optimizing search engine conversion rates slashed the company's average customer-acquisition-cost from $450 down to $280.", 'example_vi': 'Tối ưu hóa tỷ lệ chuyển đổi trên công cụ tìm kiếm đã cắt giảm chi phí thu hút khách hàng CAC trung bình từ 450 USD xuống 280 USD.', 'synonyms': ['CAC metric'], 'collocations': ['reduce customer-acquisition-cost'], 'etymology': 'Cost of acquiring a customer'},
        {'word': 'customer-lifetime-value', 'phonetic': '/ˈkʌstəmər ˈlaɪftaɪm ˌvæljuː/', 'pos': 'n', 'meaning_vi': 'giá trị trọn đời của một khách hàng trong suốt thời gian sử dụng dịch vụ (CLV)', 'definition': 'a metric that indicates the total net profit or revenue a business can expect from a single customer account throughout their relationship', 'example': 'Subscription SaaS companies focus heavily on customer retention because high customer-lifetime-value offsets high upfront CAC.', 'example_vi': 'Các công ty SaaS đăng ký tập trung mạnh vào việc giữ chân khách hàng vì giá trị trọn đời CLV cao sẽ bù đắp cho chi phí thu hút CAC ban đầu.', 'synonyms': ['CLV profitability metric'], 'collocations': ['maximize customer-lifetime-value'], 'etymology': 'Value of customer across their lifetime'},
        {'word': 'cross-selling', 'phonetic': '/ˈkrɒs ˌsɛlɪŋ/', 'pos': 'n', 'meaning_vi': 'bán chéo các sản phẩm bổ trợ liên quan cho khách hàng hiện tại', 'definition': 'the practice of selling additional, related, or complementary products or services to an existing customer', 'example': 'The retail banker excelled at cross-selling, offering mortgage customers credit cards and high-yield savings accounts.', 'example_vi': 'Nhân viên ngân hàng bán lẻ rất giỏi bán chéo, chào mời khách hàng vay mua nhà mở thêm thẻ tín dụng và tài khoản tiết kiệm lãi suất cao.', 'synonyms': ['complementary product sales'], 'collocations': ['boost cross-selling'], 'etymology': 'Selling across product lines'},
        {'word': 'upselling', 'phonetic': '/ˈʌpˌsɛlɪŋ/', 'pos': 'n', 'meaning_vi': 'bán gia tăng nâng cấp khách hàng lên phiên bản cao cấp hoặc dung lượng lớn hơn', 'definition': 'a sales technique where a seller encourages the customer to purchase a higher-end, upgraded, or more expensive version of an item', 'example': 'The car dealership salesperson used upselling to persuade the buyer to choose the turbocharged all-wheel-drive luxury trim package.', 'example_vi': 'Nhân viên bán xe đại lý đã dùng kỹ thuật bán gia tăng để thuyết phục người mua chọn gói nâng cấp dẫn động bốn bánh tăng áp sang trọng.', 'synonyms': ['premium tier upgrading'], 'collocations': ['practice effective upselling'], 'etymology': 'Selling upwards to higher tier'},
        {'word': 'value-proposition', 'phonetic': '/ˈvæljuː ˌprɒpəˈzɪʃən/', 'pos': 'n', 'meaning_vi': 'tuyên bố giá trị khác biệt cốt lõi mà sản phẩm mang lại cho khách hàng', 'definition': 'an innovation, service, or feature intended to make a company or product attractive to customers, explaining why it solves their problem', 'example': "The startup's core value-proposition was delivering ninety percent faster tax compliance processing at half the price of legacy software.", 'example_vi': 'Tuyên bố giá trị cốt lõi của công ty khởi nghiệp là mang lại quy trình tuân thủ thuế nhanh hơn 90% với giá chỉ bằng một nửa phần mềm cũ.', 'synonyms': ['unique selling proposition (USP)'], 'collocations': ['articulate a compelling value-proposition'], 'etymology': 'Proposition of unique business value'},
        {'word': 'closing-technique', 'phonetic': '/ˈkloʊzɪŋ tɛkˌniːk/', 'pos': 'n', 'meaning_vi': 'kỹ thuật chốt đơn bán hàng thúc đẩy khách hàng ký kết', 'definition': 'the method or interpersonal strategy used by a sales representative to persuade a prospect to finalize the purchase agreement', 'example': "The veteran enterprise rep used the 'assumptive closing-technique', presenting the implementation schedule as if the deal was already won.", 'example_vi': "Đại diện bán hàng doanh nghiệp kỳ cựu đã sử dụng kỹ thuật 'chốt đơn mặc định', trình bày lịch trình triển khai như thể hợp đồng đã được chốt.", 'synonyms': ['deal finalization method'], 'collocations': ['master closing-techniques'], 'etymology': 'Technique for closing sales deals'},
        {'word': 'consultative-selling', 'phonetic': '/kənˈsʌltətɪv ˌsɛlɪŋ/', 'pos': 'n', 'meaning_vi': 'bán hàng theo phương pháp tư vấn thấu hiểu sâu sắc nhu cầu khách hàng', 'definition': 'a sales approach that prioritizes relationships and open dialogue, identifying customer pain points before recommending customized solutions', 'example': 'Enterprise software requires consultative-selling, where account managers act as trusted industry advisors rather than pushy salesmen.', 'example_vi': 'Phần mềm doanh nghiệp đòi hỏi phương pháp bán hàng tư vấn, nơi các giám đốc quan hệ khách hàng đóng vai trò cố vấn đáng tin cậy.', 'synonyms': ['solution-focused advisory sales'], 'collocations': ['adopt consultative-selling'], 'etymology': 'Selling via consultation and advisory'},
        {'word': 'win-win-negotiation', 'phonetic': '/ˌwɪn ˈwɪn nɪˌɡoʊʃiˈeɪʃən/', 'pos': 'n', 'meaning_vi': 'đàm phán cùng thắng đôi bên cùng đạt được lợi ích tối ưu', 'definition': 'a collaborative negotiation style aimed at finding a mutually acceptable agreement that satisfies the underlying interests of both sides', 'example': 'Both chief executives prioritized a win-win-negotiation, trading pricing discounts for a multi-year exclusive distribution rights commitment.', 'example_vi': 'Cả hai giám đốc điều hành đều ưu tiên đàm phán cùng thắng, đánh đổi mức chiết khấu giá lấy cam kết quyền phân phối độc quyền nhiều năm.', 'synonyms': ['integrative bargaining'], 'collocations': ['achieve a win-win-negotiation'], 'etymology': 'Negotiation where both sides win'},
        {'word': 'best-alternative-to-a-negotiated-agreement', 'phonetic': '/bɛst ɔːlˈtɜːrnətɪv tə ə nɪˈɡoʊʃieɪtɪd əˌɡriːmənt/', 'pos': 'n', 'meaning_vi': 'phương án thay thế tốt nhất khi đàm phán không thành (BATNA)', 'definition': 'the most advantageous course of action a party can take if negotiations fail and an agreement cannot be reached (BATNA)', 'example': 'Knowing she held a lucrative backup job offer gave the candidate an exceptionally strong BATNA during salary negotiations.', 'example_vi': 'Việc biết mình có một lời mời làm việc dự phòng hấp dẫn đã mang lại cho ứng viên một BATNA cực kỳ vững chắc khi đàm phán lương.', 'synonyms': ['BATNA fallback option'], 'collocations': ['identify your BATNA'], 'etymology': 'Best Alternative To a Negotiated Agreement'},
        {'word': 'zone-of-possible-agreement', 'phonetic': '/zoʊn əv ˌpɒsəbl əˌɡriːmənt/', 'pos': 'n', 'meaning_vi': 'vùng khả thi để đạt được thỏa thuận giữa người mua và người bán (ZOPA)', 'definition': "the range in a negotiation in which an agreement is satisfactory to both parties, lying between each party's reservation prices", 'example': "Negotiators discovered a viable zone-of-possible-agreement between the seller's $5 million minimum and the buyer's $5.5 million ceiling.", 'example_vi': 'Các nhà đàm phán đã phát hiện một vùng thỏa thuận khả thi ZOPA nằm giữa mức giá sàn 5 triệu USD của bên bán và mức trần 5,5 triệu của bên mua.', 'synonyms': ['ZOPA bargaining overlap'], 'collocations': ['reach inside the zone-of-possible-agreement'], 'etymology': 'Zone Of Possible Agreement'},
        {'word': 'reservation-price', 'phonetic': '/ˌrɛzərˈveɪʃən praɪs/', 'pos': 'n', 'meaning_vi': 'mức giá sàn hoặc giá trần giới hạn mà một bên không thể vượt qua (Walk-away price)', 'definition': 'the absolute highest price a buyer is willing to pay or the lowest price a seller will accept before walking away from the table', 'example': 'The CFO set a strict reservation-price of twelve dollars per share, ordering the team to abandon talks if the target demanded more.', 'example_vi': 'Giám đốc tài chính đã đặt ra mức giá giới hạn nghiêm ngặt là 12 USD/cổ phiếu, ra lệnh cho nhóm từ bỏ đàm phán nếu mục tiêu đòi hỏi nhiều hơn.', 'synonyms': ['walk-away limit price'], 'collocations': ['never exceed the reservation-price'], 'etymology': 'Price reserved as the walking-away limit'},
        {'word': 'walk-away-point', 'phonetic': '/ˈwɔːk əweɪ pɔɪnt/', 'pos': 'n', 'meaning_vi': 'điểm giới hạn quyết định từ bỏ đàm phán khi điều kiện quá bất lợi', 'definition': 'the specific non-negotiable threshold or limit at which a negotiator decides it is more advantageous to walk away than to accept the deal', 'example': 'Establishing a clear walk-away-point prevented the purchasing committee from succumbing to high-pressure deadline tactics.', 'example_vi': 'Việc thiết lập điểm từ bỏ rõ ràng đã ngăn không cho ủy ban mua sắm bị khuất phục trước các chiến thuật ép tiến độ căng thẳng.', 'synonyms': ['negotiation departure threshold'], 'collocations': ['establish a walk-away-point'], 'etymology': 'Point at which one walks away'},
        {'word': 'anchoring-effect', 'phonetic': '/ˈæŋkərɪŋ ɪˌfɛkt/', 'pos': 'n', 'meaning_vi': 'hiệu ứng mỏ neo tâm lý dựa dẫm vào con số đề xuất đầu tiên', 'definition': "a cognitive bias where individuals rely too heavily on an initial piece of information offered (the 'anchor') when making decisions", 'example': 'By opening with an aggressive initial list price of ten million dollars, the seller benefited from a psychological anchoring-effect.', 'example_vi': 'Bằng cách mở đầu bằng mức giá niêm yết ban đầu mạnh dạn 10 triệu USD, người bán đã được hưởng lợi từ hiệu ứng mỏ neo tâm lý.', 'synonyms': ['cognitive price anchoring'], 'collocations': ['exploit the anchoring-effect'], 'etymology': 'Anchoring decisions on initial numbers'},
        {'word': 'concession-strategy', 'phonetic': '/kənˈsɛʃən ˈstrætədʒi/', 'pos': 'n', 'meaning_vi': 'chiến lược nhượng bộ từng bước có tính toán trong đàm phán', 'definition': 'a structured plan detailing which contractual terms or price points a party is willing to give up in exchange for reciprocal concessions', 'example': 'A skilled negotiator uses a measured concession-strategy, never offering a price discount without demanding quicker payment terms.', 'example_vi': 'Một nhà đàm phán lành nghề sử dụng chiến lược nhượng bộ có tính toán, không bao giờ giảm giá mà không đòi hỏi thanh toán nhanh hơn.', 'synonyms': ['give-and-take tactical plan'], 'collocations': ['formulate a concession-strategy'], 'etymology': 'Strategy for making mutual concessions'},
        {'word': 'hardball-tactics', 'phonetic': '/ˈhɑːrdbɔːl ˌtæktɪks/', 'pos': 'n', 'meaning_vi': 'các chiêu trò đàm phán cứng rắn gây áp lực tối đa lên đối phương', 'definition': 'aggressive, non-collaborative bargaining techniques designed to pressure, intimidate, or wear down an opponent (e.g., take-it-or-leave-it)', 'example': 'Experienced procurement directors recognize hardball-tactics like artificial deadlines and good-cop-bad-cop routines immediately.', 'example_vi': "Các giám đốc thu mua giàu kinh nghiệm nhận diện ngay các chiêu trò cứng rắn như thời hạn giả tạo hay bài diễn 'kẻ đấm người xoa'.", 'synonyms': ['aggressive bargaining maneuvers'], 'collocations': ['counter hardball-tactics'], 'etymology': 'Tactics playing hardball politics'},
        {'word': 'reciprocity-principle', 'phonetic': '/ˌrɛsɪˈprɒsəti ˌprɪnsəpl/', 'pos': 'n', 'meaning_vi': 'nguyên tắc tương hỗ có qua có lại trong thỏa thuận kinh doanh', 'definition': 'the social and psychological norm that people feel obliged to return favors, concessions, or kind gestures granted to them by others', 'example': 'The account manager leveraged the reciprocity-principle by offering free premium training before requesting an annual contract renewal.', 'example_vi': 'Giám đốc quan hệ khách hàng đã tận dụng nguyên tắc tương hỗ bằng cách cung cấp khóa đào tạo miễn phí trước khi đề nghị gia hạn hợp đồng.', 'synonyms': ['mutual give-and-take principle'], 'collocations': ['invoke the reciprocity-principle'], 'etymology': 'Principle of reciprocal exchanges'},
        {'word': 'deadlock', 'phonetic': '/ˈdɛdlɒk/', 'pos': 'n', 'meaning_vi': 'tình trạng bế tắc hoàn toàn trong đàm phán khi hai bên không chịu nhượng bộ', 'definition': 'a state of inaction or standstill resulting from the opposition of two uncompromising parties in a labor or commercial negotiation', 'example': 'Talks reached an intractable deadlock when neither side would compromise on the proprietary software intellectual property rights.', 'example_vi': 'Các cuộc đàm phán đã rơi vào bế tắc nan giải khi không bên nào chịu thỏa hiệp về quyền sở hữu trí tuệ của phần mềm độc quyền.', 'synonyms': ['stalemate', 'impasse'], 'collocations': ['break a negotiation deadlock'], 'etymology': 'Lock in dead standstill'},
        {'word': 'impasse', 'phonetic': '/æmˈpɑːs/', 'pos': 'n', 'meaning_vi': 'sự ngõ cụt bế tắc không tìm thấy lối thoát trong thương lượng', 'definition': 'a situation in which no progress is possible, especially because of disagreement, requiring outside mediation or fresh proposals', 'example': 'To overcome the contract impasse, both CEOs agreed to bring in an independent third-party commercial mediator.', 'example_vi': 'Để vượt qua ngõ cụt bế tắc của hợp đồng, cả hai CEO đã đồng ý mời một hòa giải viên thương mại độc lập của bên thứ ba.', 'synonyms': ['negotiation bottleneck/stalemate'], 'collocations': ['reach an impasse'], 'etymology': 'Impasse (dead-end alley in French)'},
        {'word': 'counter-offer', 'phonetic': '/ˈkaʊntər ˌɔːfər/', 'pos': 'n', 'meaning_vi': 'lời đề nghị trả giá ngược lại bác bỏ đề xuất trước đó', 'definition': 'an offer made in response to another offer, which legally rejects the initial offer and presents a modified proposal for consideration', 'example': "The procurement team rejected the vendor's initial quote and submitted a counter-offer seeking a fifteen percent volume discount.", 'example_vi': 'Nhóm thu mua đã từ chối báo giá ban đầu của nhà cung cấp và đưa ra một đề nghị trả giá ngược lại yêu cầu chiết khấu 15% theo sản lượng.', 'synonyms': ['counterproposal'], 'collocations': ['table a counter-offer'], 'etymology': 'Offer countering previous proposal'},
        {'word': 'carve-out-clause', 'phonetic': '/ˈkɑːrv aʊt klɔːz/', 'pos': 'n', 'meaning_vi': 'điều khoản ngoại lệ loại trừ một số trường hợp cụ thể khỏi nghĩa vụ chung', 'definition': 'a contractual provision that specifically exempts certain categories, assets, or events from the scope of an agreement', 'example': 'The intellectual property assignment included a carve-out-clause protecting patents developed by the founder prior to incorporation.', 'example_vi': 'Thỏa thuận chuyển giao quyền sở hữu trí tuệ bao gồm điều khoản ngoại lệ bảo vệ các bằng sáng chế do người sáng lập phát triển trước khi thành lập.', 'synonyms': ['exception exemption clause'], 'collocations': ['negotiate a carve-out-clause'], 'etymology': 'Clause carving out specific exemptions'},
        {'word': 'boiler-plate-language', 'phonetic': '/ˈbɔɪlər pleɪt ˈlæŋɡwɪdʒ/', 'pos': 'n', 'meaning_vi': 'ngôn ngữ mẫu tiêu chuẩn lặp đi lặp lại ở cuối các hợp đồng pháp lý', 'definition': 'standardized text, clauses, or legal language that can be reused in contracts without significant changes (e.g., notice addresses)', 'example': 'Although many treat boiler-plate-language casually, standard jurisdiction and venue clauses can dictate the outcome of litigation.', 'example_vi': 'Mặc dù nhiều người coi thường ngôn ngữ mẫu tiêu chuẩn, nhưng các điều khoản tòa án có thẩm quyền có thể quyết định kết quả kiện tụng.', 'synonyms': ['standard standardized contract clauses'], 'collocations': ['review boiler-plate-language'], 'etymology': 'Plate stamped out repeatedly like boiler iron'},
        {'word': 'indemnity-bond', 'phonetic': '/ɪnˈdɛmnəti bɒnd/', 'pos': 'n', 'meaning_vi': 'chứng thư bảo lãnh bồi thường cam kết chi trả tổn thất tài chính', 'definition': 'a legal agreement where one party guarantees to compensate another for any potential loss, damage, or legal liability incurred', 'example': 'The government required the contractor to post a five-million-dollar indemnity-bond before breaking ground on the municipal bridge.', 'example_vi': 'Chính phủ yêu cầu nhà thầu phải nộp một chứng thư bảo lãnh bồi thường trị giá 5 triệu USD trước khi khởi công xây dựng cầu thành phố.', 'synonyms': ['surety bond of indemnity'], 'collocations': ['post an indemnity-bond'], 'etymology': 'Bond indemnifying against losses'},
        {'word': 'sole-source-contract', 'phonetic': '/ˈsoʊl sɔːrs ˈkɒntrækt/', 'pos': 'n', 'meaning_vi': 'hợp đồng chỉ định thầu trực tiếp không qua đấu thầu cạnh tranh', 'definition': 'a contract awarded to a specific supplier without competitive bidding, typically because only that vendor possesses required capabilities', 'example': 'The defense department awarded a sole-source-contract to the aerospace firm for specialized stealth composite components.', 'example_vi': 'Bộ quốc phòng đã trao hợp đồng chỉ định thầu trực tiếp cho công ty hàng không vũ trụ đối với các bộ phận composite tàng hình chuyên dụng.', 'synonyms': ['non-competitive single-source award'], 'collocations': ['award a sole-source-contract'], 'etymology': 'Contract sourced solely from one supplier'},
        {'word': 'subcontractor-agreement', 'phonetic': '/sʌbˈkɒntræktər əˌɡriːmənt/', 'pos': 'n', 'meaning_vi': 'hợp đồng giao thầu phụ giữa nhà thầu chính và nhà thầu phụ', 'definition': 'a legal contract between a primary contractor and a third party who agrees to perform a specific portion of the prime contract duties', 'example': 'The prime engineering contractor executed a subcontractor-agreement with a geotechnical firm to conduct soil bore testing.', 'example_vi': 'Nhà thầu kỹ thuật chính đã ký hợp đồng thầu phụ với một công ty địa kỹ thuật để tiến hành thí nghiệm khoan đất.', 'synonyms': ['sub-vendor agreement'], 'collocations': ['execute a subcontractor-agreement'], 'etymology': 'Agreement with a secondary subcontractor'},
        {'word': 'vendor-managed-inventory', 'phonetic': '/ˈvɛndər ˈmænɪdʒd ˈɪnvəntri/', 'pos': 'n', 'meaning_vi': 'quản lý hàng tồn kho do nhà cung cấp trực tiếp chịu trách nhiệm (VMI)', 'definition': 'a business model in which the buyer of a product provides information to a vendor and the vendor assumes full responsibility for inventory levels', 'example': 'Implementing vendor-managed-inventory allowed the assembly plant to shift component carrying costs entirely to its bolt suppliers.', 'example_vi': 'Triển khai hệ thống quản lý kho do nhà cung cấp đảm nhận VMI đã cho phép nhà máy lắp ráp chuyển toàn bộ chi phí lưu kho linh kiện cho nhà cung cấp.', 'synonyms': ['VMI inventory replenishment'], 'collocations': ['adopt vendor-managed-inventory'], 'etymology': 'Inventory managed directly by vendors'},
        {'word': 'blanket-purchase-order', 'phonetic': '/ˈblæŋkɪt ˈpɜːrtʃəs ˌɔːrdər/', 'pos': 'n', 'meaning_vi': 'đơn đặt hàng mở dài hạn cho phép giao hàng làm nhiều đợt trong năm (BPO)', 'definition': 'a long-term agreement between a buyer and a supplier to deliver goods or services at predetermined prices on an as-needed release basis', 'example': 'The hospital network issued an annual blanket-purchase-order for two million medical nitrile gloves, releasing shipments monthly.', 'example_vi': 'Mạng lưới bệnh viện đã phát hành đơn đặt hàng mở dài hạn cho 2 triệu găng tay y tế nitrile, nhận hàng chia đều hàng tháng.', 'synonyms': ['standing open purchase order'], 'collocations': ['issue a blanket-purchase-order'], 'etymology': 'Purchase order blanketing extended period'},
        {'word': 'consignment-inventory', 'phonetic': '/kənˈsaɪnmənt ˈɪnvəntri/', 'pos': 'n', 'meaning_vi': 'hàng gửi bán đại lý chỉ thanh toán khi đã bán được cho khách cuối', 'definition': 'a supply chain arrangement in which goods are placed in the physical custody of a retailer, but the supplier retains legal ownership until sold', 'example': 'Under the consignment-inventory arrangement, the art gallery owes no payment to the sculptors until statues are purchased by patrons.', 'example_vi': 'Theo thỏa thuận hàng gửi bán, phòng trưng bày không phải thanh toán tiền cho các nhà điêu khắc cho đến khi tác phẩm được khách mua.', 'synonyms': ['custodial retail stock'], 'collocations': ['hold on consignment-inventory'], 'etymology': 'Inventory consigned for sale'},
        {'word': 'bill-and-hold', 'phonetic': '/ˌbɪl ənd ˈhoʊld/', 'pos': 'n', 'meaning_vi': 'nghiệp vụ xuất hóa đơn trước nhưng giữ hàng tại kho bên bán theo yêu cầu của khách', 'definition': 'a sales arrangement where a seller invoices a customer for goods, but delays physical delivery until a later agreed date upon request', 'example': 'Accounting auditors scrutinized the bill-and-hold transaction to ensure the buyer specifically requested delayed delivery in writing.', 'example_vi': 'Các kiểm toán viên kế toán đã xem xét kỹ giao dịch xuất hóa đơn giữ hàng để đảm bảo bên mua có văn bản yêu cầu giao hàng chậm.', 'synonyms': ['invoiced deferred delivery'], 'collocations': ['qualify for bill-and-hold'], 'etymology': 'Billing buyer and holding inventory'},
        {'word': 'volume-rebate', 'phonetic': '/ˈvɒljuːm ˌriːbeɪt/', 'pos': 'n', 'meaning_vi': 'khoản tiền thưởng chiết khấu theo doanh số tích lũy cuối kỳ', 'definition': 'a financial payment made to a buyer by a supplier based on reaching specified cumulative purchasing volume thresholds over a fiscal year', 'example': 'Surpassing ten million dollars in annual orders earned the supermarket chain a five percent volume-rebate check at year-end.', 'example_vi': 'Việc vượt mức 10 triệu USD đơn đặt hàng hàng năm đã giúp chuỗi siêu thị nhận được séc tiền thưởng theo sản lượng 5% vào cuối năm.', 'synonyms': ['bulk purchase retrospective refund'], 'collocations': ['earn a volume-rebate'], 'etymology': 'Rebate calculated on sales volume'},
        {'word': 'early-payment-discount', 'phonetic': '/ˈɜːrli ˈpeɪmənt ˈdɪskaʊnt/', 'pos': 'n', 'meaning_vi': 'chiết khấu thanh toán sớm khuyến khích trả tiền ngay (ví dụ 2/10 net 30)', 'definition': 'a price incentive offered by a seller that permits a buyer to deduct a percentage of the total invoice if paid well before the due date', 'example': "The supplier offered terms of '2/10 net 30', granting an early-payment-discount of two percent if the invoice was settled within ten days.", 'example_vi': "Nhà cung cấp đưa ra điều khoản '2/10 net 30', giảm giá thanh toán sớm 2% nếu hóa đơn được tất toán trong vòng 10 ngày.", 'synonyms': ['cash settlement discount incentive'], 'collocations': ['take advantage of early-payment-discounts'], 'etymology': 'Discount encouraging early invoice settlement'},
        {'word': 'net-thirty-days', 'phonetic': '/ˌnɛt ˈθɜːrti deɪz/', 'pos': 'n', 'meaning_vi': 'điều khoản thanh toán tiền trong vòng 30 ngày kể từ ngày xuất hóa đơn', 'definition': 'a commercial payment term indicating that the full invoice amount is due thirty calendar days after the date of invoice issuance', 'example': 'Most enterprise procurement departments operate strictly on net-thirty-days payment terms to optimize cash flow management.', 'example_vi': 'Hầu hết các phòng mua sắm doanh nghiệp vận hành nghiêm ngặt theo điều khoản thanh toán net 30 ngày để tối ưu hóa dòng tiền.', 'synonyms': ['30-day payment term'], 'collocations': ['bill on net-thirty-days'], 'etymology': 'Payment due net in thirty days'},
        {'word': 'turnkey-solution', 'phonetic': '/ˈtɜːrnkiː səˌluːʃən/', 'pos': 'n', 'meaning_vi': 'giải pháp chìa khóa trao tay hoàn thiện đầy đủ chỉ việc vận hành ngay', 'definition': 'a product or service that is designed, supplied, and installed complete and ready for immediate operation without additional engineering', 'example': 'The hospital contracted for a turnkey-solution, requiring the contractor to furnish, wire, test, and calibrate the entire ICU wing.', 'example_vi': 'Bệnh viện đã ký hợp đồng giải pháp chìa khóa trao tay, yêu cầu nhà thầu cung cấp, lắp điện, thử nghiệm và hiệu chuẩn toàn bộ khu ICU.', 'synonyms': ['all-in-one ready-to-operate package'], 'collocations': ['deliver a turnkey-solution'], 'etymology': 'Solution ready at the turn of a key'},
        {'word': 'purchase-requisition', 'phonetic': '/ˈpɜːrtʃəs ˌrɛkwɪˈzɪʃən/', 'pos': 'n', 'meaning_vi': 'phiếu yêu cầu mua sắm nội bộ gửi phòng vật tư', 'definition': 'an internal document used by an employee to request the purchase of goods or services on behalf of their department', 'example': 'The laboratory technician submitted a purchase-requisition for fifty cases of sterile pipette tips and reagents.', 'example_vi': 'Kỹ thuật viên phòng thí nghiệm đã nộp phiếu yêu cầu mua sắm 50 thùng đầu côn pipette vô trùng và hóa chất.', 'synonyms': ['internal buy request'], 'collocations': ['submit a purchase-requisition'], 'etymology': 'Requisition to make a purchase'},
        {'word': 'letter-of-intent', 'phonetic': '/ˈlɛtər əv ɪnˈtɛnt/', 'pos': 'n', 'meaning_vi': 'thư bày tỏ ý định hợp tác hoặc mua bán trước khi ký hợp đồng chính thức (LOI)', 'definition': 'a document declaring the preliminary intention of one party to do business with another, summarizing major terms', 'example': 'Both corporations signed a non-binding letter-of-intent outlining the proposed forty-million-dollar asset acquisition.', 'example_vi': 'Cả hai tập đoàn đã ký một thư bày tỏ ý định không ràng buộc phác thảo thương vụ mua lại tài sản trị giá 40 triệu USD.', 'synonyms': ['LOI preliminary term sheet'], 'collocations': ['execute a letter-of-intent'], 'etymology': 'Letter stating formal business intent'},
        {'word': 'memorandum-of-agreement', 'phonetic': '/ˌmɛməˈrændəm əv əˈɡriːmənt/', 'pos': 'n', 'meaning_vi': 'biên bản thỏa thuận hợp tác thương mại (MOA)', 'definition': 'a formal document written between parties to cooperatively work together on an agreed-upon project or meet an objective', 'example': 'The universities executed a memorandum-of-agreement to exchange faculty members and co-fund clean energy laboratories.', 'example_vi': 'Các trường đại học đã ký kết biên bản thỏa thuận MOA để trao đổi giảng viên và đồng tài trợ các phòng thí nghiệm năng lượng sạch.', 'synonyms': ['MOA partnership pact'], 'collocations': ['draft a memorandum-of-agreement'], 'etymology': 'Memorandum establishing agreement'},
        {'word': 'non-compete-clause', 'phonetic': '/ˌnɒn kəmˈpiːt klɔːz/', 'pos': 'n', 'meaning_vi': 'điều khoản chống cạnh tranh cấm làm việc cho đối thủ trong thời gian quy định', 'definition': 'a contractual clause stating that an employee or seller will not enter into competition with the business for a specific time and area', 'example': 'The executive employment contract included a twelve-month non-compete-clause barring her from joining direct market rivals.', 'example_vi': 'Hợp đồng lao động của giám đốc điều hành bao gồm điều khoản chống cạnh tranh 12 tháng cấm cô làm việc cho các đối thủ trực tiếp.', 'synonyms': ['restrictive covenant'], 'collocations': ['enforce a non-compete-clause'], 'etymology': 'Clause preventing unfair competition'},
        {'word': 'non-solicitation-clause', 'phonetic': '/ˌnɒn səˌlɪsɪˈteɪʃən klɔːz/', 'pos': 'n', 'meaning_vi': 'điều khoản cấm lôi kéo khách hàng hoặc nhân viên cũ', 'definition': "a contract agreement in which one party agrees not to solicit or recruit the other party's clients, customers, or employees", 'example': 'Upon resigning, the sales director honored the non-solicitation-clause by refraining from contacting former corporate accounts.', 'example_vi': 'Khi từ chức, giám đốc bán hàng đã tuân thủ điều khoản cấm lôi kéo bằng cách không liên hệ với các tài khoản khách hàng doanh nghiệp cũ.', 'synonyms': ['anti-poaching restriction'], 'collocations': ['abide by a non-solicitation-clause'], 'etymology': 'Clause forbidding client solicitation'},
        {'word': 'change-order', 'phonetic': '/ˈtʃeɪndʒ ˌɔːrdər/', 'pos': 'n', 'meaning_vi': 'văn bản yêu cầu thay đổi thiết kế hoặc phạm vi công việc trong dự án xây dựng', 'definition': 'work that is added to or deleted from the original scope of work of a contract, altering the original contract amount or completion date', 'example': 'The client requested custom Italian marble flooring, requiring a thirty-thousand-dollar change-order and a two-week schedule delay.', 'example_vi': 'Khách hàng yêu cầu sàn đá cẩm thạch Ý theo thiết kế riêng, đòi hỏi văn bản yêu cầu thay đổi trị giá 30.000 USD và lùi tiến độ 2 tuần.', 'synonyms': ['scope variation order'], 'collocations': ['approve a change-order'], 'etymology': 'Order changing contract terms'},
        {'word': 'scope-creep', 'phonetic': '/ˈskoʊp kriːp/', 'pos': 'n', 'meaning_vi': 'hiện tượng phình to phạm vi công việc ngoài tầm kiểm soát và ngân sách', 'definition': "uncontrolled growth or continuous expansion in a project's scope at any point after the project begins, without adjustments to time or budget", 'example': 'Without disciplined project governance, minor client feature requests led to disastrous scope-creep and severe budget overruns.', 'example_vi': 'Nếu không có sự quản trị dự án kỷ luật, các yêu cầu tính năng nhỏ của khách hàng sẽ dẫn đến hiện tượng phình to phạm vi công việc thảm khốc.', 'synonyms': ['uncontrolled scope expansion'], 'collocations': ['prevent scope-creep'], 'etymology': 'Scope creeping beyond contract limits'},
        {'word': 'milestone-payment', 'phonetic': '/ˈmaɪlstoʊn ˌpeɪmənt/', 'pos': 'n', 'meaning_vi': 'thanh toán theo từng mốc tiến độ hoàn thành công việc', 'definition': 'a pre-agreed installment of payment made when a contractor or service provider reaches a specific predefined stage in a project', 'example': 'The software contract tied the second twenty-five percent milestone-payment to the successful completion of user acceptance testing.', 'example_vi': 'Hợp đồng phần mềm đã gắn đợt thanh toán theo mốc 25% thứ hai với việc hoàn thành thành công thử nghiệm chấp nhận của người dùng.', 'synonyms': ['progress installment payment'], 'collocations': ['release a milestone-payment'], 'etymology': 'Payment upon reaching project milestones'},
        {'word': 'retainage', 'phonetic': '/rɪˈteɪnɪdʒ/', 'pos': 'n', 'meaning_vi': 'tiền giữ lại bảo hành công trình chờ nghiệm thu dứt điểm (thường 5-10%)', 'definition': 'a portion of the agreed upon contract price deliberately withheld until the work is substantially complete to assure that contractor will satisfy its obligations', 'example': 'The developer withheld ten percent retainage from every monthly pay app until the final punch-list items were certified.', 'example_vi': 'Chủ đầu tư đã giữ lại 10% tiền bảo hành từ mỗi phiếu thanh toán hàng tháng cho đến khi các mục trong danh sách tồn đọng được xác nhận.', 'synonyms': ['withheld retention money'], 'collocations': ['withhold retainage'], 'etymology': 'Money retained as warranty guarantee'},
        {'word': 'performance-bond', 'phonetic': '/pərˈfɔːrməns bɒnd/', 'pos': 'n', 'meaning_vi': 'bảo lãnh thực hiện hợp đồng cam kết bồi thường nếu nhà thầu bỏ dở', 'definition': 'a surety bond issued by an insurance company or bank to guarantee satisfactory completion of a project by a contractor', 'example': 'The general contractor submitted a performance-bond equal to one hundred percent of the fifty-million-dollar highway bid price.', 'example_vi': 'Nhà thầu chính đã nộp chứng thư bảo lãnh thực hiện hợp đồng tương đương 100% giá trúng thầu dự án đường cao tốc 50 triệu USD.', 'synonyms': ['contract completion surety'], 'collocations': ['secure a performance-bond'], 'etymology': 'Bond guaranteeing contractual performance'},
        {'word': 'bid-bond', 'phonetic': '/ˈbɪd bɒnd/', 'pos': 'n', 'meaning_vi': 'bảo lãnh dự thầu cam kết ký hợp đồng nếu trúng thầu', 'definition': 'a debt secured by a bidder for a construction job or similar type of bid-based selection process to ensure the bidder will accept the job', 'example': "Submitting a certified cashier's check or five percent bid-bond was mandatory to qualify for the municipal waterworks tender.", 'example_vi': 'Nộp séc thu ngân có bảo chứng hoặc chứng thư bảo lãnh dự thầu 5% là điều kiện bắt buộc để đủ tư cách dự thầu công trình cấp nước đô thị.', 'synonyms': ['tendering surety bond'], 'collocations': ['post a bid-bond'], 'etymology': 'Bond securing an official bid'},
        {'word': 'payment-bond', 'phonetic': '/ˈpeɪmənt bɒnd/', 'pos': 'n', 'meaning_vi': 'bảo lãnh thanh toán đảm bảo nhà thầu trả tiền cho nhà thầu phụ và nhân công', 'definition': 'a surety bond posted by a contractor to guarantee that its subcontractors and material suppliers on the project will be paid', 'example': 'Federal Miller Act regulations mandate a payment-bond on all public building projects to shield suppliers from contractor bankruptcy.', 'example_vi': 'Quy định Đạo luật Miller liên bang bắt buộc phải có bảo lãnh thanh toán trên mọi dự án công để bảo vệ nhà cung cấp trước phá sản.', 'synonyms': ['labor and material surety'], 'collocations': ['file a claim against the payment-bond'], 'etymology': 'Bond guaranteeing supplier payment'},
        {'word': 'letters-of-credit', 'phonetic': '/ˈlɛtərz əv ˈkrɛdɪt/', 'pos': 'n', 'meaning_vi': 'thư tín dụng ngân hàng cam kết thanh toán quốc tế (L/C)', 'definition': "a letter from a bank guaranteeing that a buyer's payment to a seller will be received on time and for the correct amount upon presentation of docs", 'example': 'The exporter refused to ship the containerized heavy machinery without an irrevocable, confirmed commercial letter-of-credit.', 'example_vi': 'Nhà xuất khẩu đã từ chối bốc xếp máy móc hạng nặng lên container nếu không có thư tín dụng L/C thương mại xác nhận, không hủy ngang.', 'synonyms': ['bank guarantee L/C'], 'collocations': ['open an irrevocable letter-of-credit'], 'etymology': 'Letters assuring bank credit backing'},
        {'word': 'open-account', 'phonetic': '/ˈoʊpən əˌkaʊnt/', 'pos': 'n', 'meaning_vi': 'phương thức thanh toán ghi sổ giao hàng trước trả tiền sau', 'definition': 'a sale where the goods are shipped and delivered before payment is due, typically in thirty, sixty, or ninety days, advantageous to buyers', 'example': 'Longtime multinational partners transact on open-account terms, settling aggregate invoices at the conclusion of each fiscal quarter.', 'example_vi': 'Các đối tác đa quốc gia lâu năm giao dịch theo điều khoản ghi sổ open-account, tất toán hóa đơn tổng hợp vào cuối mỗi quý tài chính.', 'synonyms': ['deferred payment terms'], 'collocations': ['sell on open-account'], 'etymology': 'Account kept open for later settlement'},
        {'word': 'pro-forma-invoice', 'phonetic': '/proʊ ˈfɔːrmə ˈɪnvɔɪs/', 'pos': 'n', 'meaning_vi': 'hóa đơn chiếu lệ báo trước thông số và giá cả phục vụ thủ tục hải quan', 'definition': 'a preliminary bill of sale sent to buyers in advance of a shipment or delivery of goods, outlining the purchased items and total charges', 'example': 'Customs officers reviewed the pro-forma-invoice to calculate estimated import duties before the ocean vessel arrived at the terminal.', 'example_vi': 'Các cán bộ hải quan đã xem xét hóa đơn chiếu lệ để tính toán thuế nhập khẩu ước tính trước khi tàu cập cảng.', 'synonyms': ['preliminary quotation invoice'], 'collocations': ['issue a pro-forma-invoice'], 'etymology': 'Invoice for the sake of form (pro forma)'},
        {'word': 'commercial-invoice', 'phonetic': '/kəˈmɜːrʃəl ˈɪnvɔɪs/', 'pos': 'n', 'meaning_vi': 'hóa đơn thương mại chính thức chứng từ xuất nhập khẩu pháp lý', 'definition': 'a legal document between the supplier and the customer that clearly describes the sold goods and the amount due on the transaction', 'example': 'The freight forwarder attached three original copies of the commercial-invoice to the ocean container shipping dossier.', 'example_vi': 'Công ty giao nhận vận tải đã đính kèm 3 bản gốc hóa đơn thương mại vào hồ sơ vận chuyển container đường biển.', 'synonyms': ['customs billing document'], 'collocations': ['certify the commercial-invoice'], 'etymology': 'Official commercial bill for customs'},
        {'word': 'packing-slip', 'phonetic': '/ˈpækɪŋ slɪp/', 'pos': 'n', 'meaning_vi': 'phiếu đóng gói hàng hóa chi tiết số lượng và quy cách từng kiện', 'definition': 'a document that includes a complete list of items included in a shipment, used by warehouse receiving teams to verify delivery contents', 'example': 'Receiving dock clerks checked each cardboard carton against the packing-slip to ensure no electronic components were missing.', 'example_vi': 'Nhân viên kho bốc dỡ đã kiểm tra từng thùng carton đối chiếu với phiếu đóng gói để đảm bảo không thiếu linh kiện điện tử nào.', 'synonyms': ['shipping bill of parcels'], 'collocations': ['attach the packing-slip'], 'etymology': 'Slip detailing packed shipment contents'},
